import { computed, ref } from "vue";
import { defineStore } from "pinia";
import { calculateXpAwardPlan } from "../../../functions/xp-curve/calculate";
import {
  createCurveDraft,
  curveExampleActors,
  CURVE_STEPS,
  validateCurveInput,
} from "../../../functions/xp-curve/setup";
import { simulateCurveSessions } from "../../../functions/xp-curve/simulation";
import {
  DEFAULT_XP_CURVE_CONFIGURATOR_SETTINGS,
  type CurveDraft,
  type XpCurveConfiguratorActions,
  type XpCurveConfiguratorInitialization,
} from "../../../../types/xp-curve/Configuration";

export const useXpCurveConfiguratorStore = defineStore("xp-curve-configurator", () => {
  const draft = ref(createCurveDraft(DEFAULT_XP_CURVE_CONFIGURATOR_SETTINGS.parameters));
  const stepIndex = ref(0);
  const initialization = ref<XpCurveConfiguratorInitialization>({
    ...DEFAULT_XP_CURVE_CONFIGURATOR_SETTINGS,
    actors: [],
  });
  const errorMessage = ref<string>();
  const statusMessage = ref<string>();
  const isWorking = ref(false);
  const saved = ref(false);
  let actions: XpCurveConfiguratorActions;
  const step = computed(() => CURVE_STEPS[stepIndex.value]!);
  const previewActors = computed(() =>
    draft.value.previewMode === "example" ? curveExampleActors() : initialization.value.actors,
  );
  const plan = computed(() => calculateXpAwardPlan(previewActors.value, draft.value.parameters));
  const hasChanges = computed(
    () =>
      !saved.value &&
      JSON.stringify(draft.value.parameters) !== JSON.stringify(initialization.value.parameters),
  );
  const inputError = computed(() =>
    step.value.key === "review"
      ? undefined
      : validateCurveInput(draft.value.parameters[step.value.key], stepIndex.value),
  );
  const forecast = computed(() => {
    try {
      return {
        rows: simulateCurveSessions(
          previewActors.value,
          draft.value.parameters,
          draft.value.sessions,
          draft.value.sessionXp,
        ),
        error: undefined,
      };
    } catch (error) {
      return {
        rows: [],
        error: error instanceof Error ? error.message : "Enter valid forecast assumptions.",
      };
    }
  });

  function initialize(
    data: XpCurveConfiguratorInitialization,
    handlers: XpCurveConfiguratorActions,
    nextDraft?: CurveDraft,
    index = 0,
  ): void {
    initialization.value = data;
    actions = handlers;
    draft.value = nextDraft
      ? { ...nextDraft, parameters: { ...nextDraft.parameters } }
      : createCurveDraft(data.parameters);
    stepIndex.value = index;
    actions.bindCloseGuard(
      async () => !isWorking.value && (!hasChanges.value || (await actions.confirmClose())),
    );
  }

  async function resetToDefaults(): Promise<void> {
    if (isWorking.value) return;
    isWorking.value = true;
    try {
      if (!(await actions.confirmReset())) return;
      draft.value.parameters = { ...DEFAULT_XP_CURVE_CONFIGURATOR_SETTINGS.parameters };
      statusMessage.value = "Defaults restored in this draft. Finish setup to save them.";
      errorMessage.value = undefined;
    } finally {
      isWorking.value = false;
    }
  }

  async function changeStep(direction: number): Promise<void> {
    if (isWorking.value || (direction > 0 && inputError.value)) return;
    isWorking.value = true;
    try {
      await actions.changeStep(
        { ...draft.value, parameters: { ...draft.value.parameters } },
        direction,
      );
    } catch (error) {
      errorMessage.value = error instanceof Error ? error.message : "Could not open the next step.";
    } finally {
      isWorking.value = false;
    }
  }

  async function saveConfiguration(): Promise<void> {
    if (isWorking.value || step.value.key !== "review") return;
    const invalid = CURVE_STEPS.slice(0, -1).findIndex(
      (entry, index) =>
        entry.key !== "review" && validateCurveInput(draft.value.parameters[entry.key], index),
    );
    if (invalid >= 0) {
      errorMessage.value = `Review step ${invalid + 1}: ${CURVE_STEPS[invalid]!.title}.`;
      return;
    }
    isWorking.value = true;
    errorMessage.value = undefined;
    try {
      await actions.saveConfiguration({
        defaultReason: initialization.value.defaultReason,
        parameters: { ...draft.value.parameters },
      });
      saved.value = true;
      isWorking.value = false;
      actions.close();
    } catch (error) {
      errorMessage.value =
        error instanceof Error ? error.message : "The configuration could not be saved.";
    } finally {
      isWorking.value = false;
    }
  }

  return {
    draft,
    stepIndex,
    step,
    initialization,
    previewActors,
    plan,
    forecast,
    hasChanges,
    inputError,
    errorMessage,
    statusMessage,
    isWorking,
    initialize,
    resetToDefaults,
    changeStep,
    saveConfiguration,
  };
});
