import type { Component } from "vue";
import type { PartyConfiguration } from "../../../../../types/party/Party";
import { ToolkitVueApplication } from "../../../../foundry/apps/ToolkitVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../../../../foundry/apps/access";
import { resetPartyConfiguration } from "../../../../foundry/party/configuration";
import { confirmRemovePartyZone } from "../../../../foundry/party/portraits";
import { confirmUnsavedPartyChanges } from "../../../../foundry/party/unsaved";
import PartyZonesApp from "./PartyZonesApp.vue";

export class PartyZonesApplication extends ToolkitVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.configureParty;
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    position: { width: 440, height: 380 },
    window: { title: "Party Zones", icon: "fa-solid fa-gear", resizable: true },
  };
  private result: PartyConfiguration | null = null;
  private closeGuard?: () => Promise<boolean>;
  private closing = false;
  constructor(
    private configuration: PartyConfiguration,
    private finish: (value: PartyConfiguration | null) => void,
  ) {
    super();
  }
  protected override getVueComponent(): Component {
    return PartyZonesApp;
  }
  override async close(): Promise<this> {
    if (this.closing) return this;
    this.closing = true;
    try {
      if (this.closeGuard && !(await this.closeGuard())) return this;
      return await super.close();
    } finally {
      this.closing = false;
    }
  }
  protected override getVueProps(): Record<string, unknown> {
    return {
      initialConfiguration: this.configuration,
      actions: {
        apply: (value: PartyConfiguration) => {
          this.result = value;
        },
        reset: resetPartyConfiguration,
        remove: confirmRemovePartyZone,
        bindCloseGuard: (guard: () => Promise<boolean>) => {
          this.closeGuard = guard;
        },
        confirmClose: () => confirmUnsavedPartyChanges(true),
        close: () => {
          void this.close();
        },
      },
    };
  }
  protected override async _preClose(
    options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<void> {
    await super._preClose(options);
    this.finish(this.result);
  }
}
