import { escapeHtml } from "../../functions/xp-curve/reason";
import { addXpAwardBatch } from "../../functions/xp-award/audit";
import { calculateFixedXpAwardPlan } from "../../functions/xp-award/calculate";
import { formatXpAwardDateTime, resolveFixedXpAwardReason } from "../../functions/xp-award/reason";
import type {
  FixedXpAward,
  XpAwardBatchRecord,
  XpAwardRequest,
  XpAwardResult,
} from "../../../types/xp-award/XpAward";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";
import { getCurrentSessionReference } from "../session-management/settings/load";
import { getXpActorRuntimes, type XpActorRuntime } from "../xp-curve/actors";
import { findRecordedXpGrant } from "../../functions/xp-award/recovery";
import { getXpAwardAuditLog, saveXpAwardAuditLog } from "./settings/load";
import { resolvePreparedXpRecipients } from "./recipients";

/**
 * Lets an interrupted batch resume without repeating a grant. `applied` holds grants recorded by an
 * earlier attempt. `logBaseline` holds each recipient's XP log length saved before the first
 * write; a later log entry with this batch's reason proves a grant whose progress save was lost.
 */
export interface XpAwardProgress {
  applied: readonly FixedXpAward[];
  logBaseline: Readonly<Record<string, number>> | undefined;
  onApplied: (award: FixedXpAward) => Promise<void>;
  onBaseline: (baseline: Record<string, number>) => Promise<void>;
}

export async function applyFixedXpAwards(
  request: XpAwardRequest,
  session?: { reference: string; reason: string },
  progress?: XpAwardProgress,
): Promise<XpAwardResult> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.xpAwards);

  const actorIds = Array.from(new Set(request.actorIds));

  if (actorIds.length === 0) {
    throw new Error("Select at least one character actor.");
  }

  if (!Number.isSafeInteger(request.defaultAmount) || request.defaultAmount === 0) {
    throw new Error("Enter a non-zero whole-number XP change.");
  }

  getXpAwardAuditLog();
  const previouslyApplied = progress?.applied ?? [];
  const appliedIds = new Set(previouslyApplied.map((award) => award.actorId));
  const pendingRuntimes = (
    request.prepared
      ? await resolvePreparedXpRecipients(request.prepared)
      : getXpActorRuntimes(actorIds.filter((id) => !appliedIds.has(id)))
  ).filter((runtime) => !appliedIds.has(runtime.choice.id));
  const awardedAt = request.prepared?.awardedAt ?? new Date().toISOString();
  const sessionReference =
    session?.reference ?? request.prepared?.sessionReference ?? getCurrentSessionReference();
  const reason =
    session?.reason ??
    request.prepared?.reason ??
    resolveFixedXpAwardReason(
      request.defaultReason,
      {
        date: awardedAt.slice(0, 10),
        datetime: formatXpAwardDateTime(awardedAt),
        session: sessionReference,
      },
      request.includeTimestampInReason,
    );

  const appliedAwards: FixedXpAward[] = [...previouslyApplied];
  const actorRuntimes: XpActorRuntime[] = [];
  const logBaseline = progress?.logBaseline;
  if (!logBaseline) {
    // Saved before any write: if this fails, nothing has changed yet.
    await progress?.onBaseline(
      Object.fromEntries(pendingRuntimes.map(({ choice, xpLog }) => [choice.id, xpLog.length])),
    );
    actorRuntimes.push(...pendingRuntimes);
  } else {
    for (const runtime of pendingRuntimes) {
      const baselineLength = logBaseline[runtime.choice.id];
      if (baselineLength === undefined)
        throw new Error(
          `The saved XP progress has no starting record for ${runtime.choice.name}. Check their XP log before continuing.`,
        );
      const recorded = findRecordedXpGrant(runtime.choice, runtime.xpLog, baselineLength, reason);
      if (!recorded) {
        actorRuntimes.push(runtime);
        continue;
      }
      appliedAwards.push(recorded);
      await progress.onApplied(recorded);
    }
  }
  const plan = calculateFixedXpAwardPlan(
    actorRuntimes.map((runtime) => runtime.choice),
    request.defaultAmount,
  );
  if (appliedAwards.length === 0 && !plan.awards.some((award) => award.amount !== 0))
    throw new Error("This amount produces no XP changes for these recipients.");

  for (const [index, runtime] of actorRuntimes.entries()) {
    const award = plan.awards[index]!;
    if (award.amount === 0) continue;

    try {
      await runtime.awardExperience(award.amount, reason);
      appliedAwards.push(award);
    } catch (error) {
      const appliedSummary =
        appliedAwards.length > 0
          ? ` XP was already changed for ${appliedAwards.map((entry) => entry.actorName).join(", ")}.`
          : "";
      const detail = error instanceof Error ? ` ${error.message}` : "";

      throw new Error(`Could not change XP for ${award.actorName}.${appliedSummary}${detail}`, {
        cause: error,
      });
    }
    await progress?.onApplied(award);
  }

  const result: XpAwardResult = {
    awards: appliedAwards,
    totalChange: appliedAwards.reduce((sum, award) => sum + award.amount, 0),
    awardedAt,
    reason,
    sessionReference,
  };
  const batch: XpAwardBatchRecord = {
    ...result,
    id: crypto.randomUUID(),
  };

  // Reporting failures must never present a completed grant as an award to retry.
  try {
    await saveXpAwardAuditLog(addXpAwardBatch(getXpAwardAuditLog(), batch));
  } catch (error) {
    console.error("Drowsy's Toolkit | XP applied, but audit history could not be saved.", error);
    ui.notifications.error(
      "XP was applied, but its toolkit audit entry could not be saved. Do not award it again; check the actors' XP logs.",
    );
  }
  try {
    await postXpAwardSummary(result);
  } catch (error) {
    console.error("Drowsy's Toolkit | XP applied, but chat summary failed.", error);
    ui.notifications.error("XP was applied, but the chat summary failed. Do not award it again.");
  }
  ui.notifications.info(
    `Applied ${formatSigned(result.totalChange)} XP to ${result.awards.length} ${result.awards.length === 1 ? "actor" : "actors"}.`,
  );

  return result;
}

async function postXpAwardSummary(result: XpAwardResult): Promise<void> {
  const rows = result.awards
    .map(
      (award) =>
        `<li><strong>${escapeHtml(award.actorName)}</strong>: ${formatSigned(award.amount)} XP ` +
        `(${award.beforeXp} → ${award.afterXp})</li>`,
    )
    .join("");
  const content =
    `<h2>XP Award</h2><p>${escapeHtml(result.reason || "No reason")}</p>` +
    `<p><small>${escapeHtml(formatXpAwardDateTime(result.awardedAt))}</small></p>` +
    `<ul>${rows}</ul><p><strong>${formatSigned(result.totalChange)} XP in total.</strong></p>`;
  const messageData = game.wfrp4e.utility.chatDataSetup(content, "gmroll", false, {
    alias: "Drowsy’s WFRP4e Toolkit",
  });

  await ChatMessage.create(messageData);
}

function formatSigned(value: number): string {
  return value > 0 ? `+${value}` : String(value);
}
