import {
  DEFAULT_XP_CURVE_SETTINGS,
  type XpActorChoice,
  type XpCurveParameters,
  type XpCurveSettings,
} from "./XpCurve";

export type XpCurveConfiguratorSettings = XpCurveSettings;

export interface XpCurveRoster {
  actors: XpActorChoice[];
  rosterIssue?: string | undefined;
}

export interface XpCurveConfiguratorInitialization extends XpCurveSettings, XpCurveRoster {}

export type CurveStep = keyof XpCurveParameters | "review";
export interface CurveDraft {
  parameters: XpCurveParameters;
  previewMode: "party" | "example";
  sessions: number;
  sessionXp: number;
}

export interface XpCurveConfiguratorActions {
  saveConfiguration: (configuration: XpCurveConfiguratorSettings) => Promise<void>;
  changeStep: (draft: CurveDraft, direction: number) => Promise<void>;
  confirmReset: () => Promise<boolean>;
  confirmClose: () => Promise<boolean>;
  bindCloseGuard: (guard: () => Promise<boolean>) => void;
  close: () => void;
  openParty: () => void;
}

export const DEFAULT_XP_CURVE_CONFIGURATOR_SETTINGS: XpCurveConfiguratorSettings = {
  ...DEFAULT_XP_CURVE_SETTINGS,
  parameters: { ...DEFAULT_XP_CURVE_SETTINGS.parameters },
};
