import type { Component } from "vue";
import type {
  CurveDraft,
  XpCurveConfiguratorActions,
  XpCurveConfiguratorInitialization,
} from "../../../../types/xp-curve/Configuration";
import { CURVE_STEPS } from "../../../functions/xp-curve/setup";
import {
  getXpCurveConfiguratorInitialization,
  saveXpCurveConfiguratorSettings,
  confirmCurveReset,
  confirmCurveCancel,
} from "../../../foundry/xp-curve/configuration";
import { MODULE_ID } from "../../../constants";
import { ToolkitVueApplication } from "../../../foundry/apps/ToolkitVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../../../foundry/apps/access";
import { openConfigureParty } from "../../configure-party/view/ConfigurePartyApplication";
import XpCurveConfiguratorApp from "./XpCurveConfiguratorApp.vue";

export class XpCurveConfiguratorApplication extends ToolkitVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.xpCurveConsole;
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-xp-curve-configurator`,
    position: { height: 740, width: 680 },
    window: { icon: "fa-solid fa-chart-line", resizable: true, title: "Configure Curve XP" },
  };
  private initialization?: XpCurveConfiguratorInitialization;
  private draft: CurveDraft | undefined;
  private stepIndex = 0;
  private closeGuard?: () => Promise<boolean>;
  private closing = false;

  override async close(): Promise<this> {
    if (this.closing) return this;
    this.closing = true;
    try {
      if (this.closeGuard && !(await this.closeGuard())) return this;
      return await super.close();
    } finally {
      this.closing = false;
    }
  }
  protected override getVueComponent(): Component {
    return XpCurveConfiguratorApp;
  }
  protected override getVueProps(): Record<string, unknown> {
    this.initialization ??= getXpCurveConfiguratorInitialization();
    const actions: XpCurveConfiguratorActions = {
      saveConfiguration: saveXpCurveConfiguratorSettings,
      changeStep: async (draft, direction) => {
        this.draft = draft;
        this.stepIndex = Math.max(0, Math.min(CURVE_STEPS.length - 1, this.stepIndex + direction));
        const fresh = getXpCurveConfiguratorInitialization();
        this.initialization = {
          ...this.initialization!,
          actors: fresh.actors,
          rosterIssue: fresh.rosterIssue,
        };
        await this.render(true);
      },
      confirmReset: confirmCurveReset,
      confirmClose: confirmCurveCancel,
      bindCloseGuard: (guard) => {
        this.closeGuard = guard;
      },
      close: () => {
        void this.close();
      },
      openParty: () => {
        void openConfigureParty();
      },
    };
    return {
      actions,
      initialization: this.initialization,
      initialDraft: this.draft,
      initialStep: this.stepIndex,
    };
  }
}
