import type { CampaignSource } from "../../../types/campaign-import";
import { PACKAGE_ID, PACKAGE_TITLE } from "../../constants";
import { requireCampaignGM } from "./content";
import { campaignImportDialogClass } from "./dialogs";

const backupName = `${PACKAGE_ID}-pc-backups`;
const backupTitle = `${PACKAGE_TITLE} — PC Backups`;
const ownership = {
  PLAYER: "NONE",
  TRUSTED: "NONE",
  ASSISTANT: "OWNER",
  GAMEMASTER: "OWNER",
};

export async function confirmPlayerCharacterUpdates(
  actors: CampaignSource[],
): Promise<boolean | null> {
  if (!actors.length) return true;
  const names = actors
    .map((actor) => `<li>${foundry.utils.escapeHTML(String(actor["name"] ?? actor._id))}</li>`)
    .join("");
  return foundry.applications.api.DialogV2.confirm({
    classes: [campaignImportDialogClass],
    window: { title: "Update Existing Player Characters?" },
    content:
      `<p><strong>This will replace these Player Characters with the campaign versions, ` +
      `including their current advances, inventory and other player edits.</strong></p><ul>${names}</ul>` +
      `<p>Before updating, a dated backup of each character will be saved in the GM-only ` +
      `<strong>${foundry.utils.escapeHTML(backupTitle)}</strong> compendium. Current ownership and user assignments stay unchanged.</p>`,
    yes: { label: "Back Up & Update", default: false },
    no: { label: "Cancel Import", default: true },
    rejectClose: false,
  });
}

/** Persist and verify every original PC before the import may change any world document. */
export async function backupPlayerCharacters(actors: CampaignSource[]): Promise<void> {
  if (!actors.length) return;
  requireCampaignGM();
  const actorClass = game?.collections.get("Actor")?.documentClass;
  if (!actorClass) throw new Error("Foundry's actor collection is unavailable.");
  const pack =
    game?.packs.get(`world.${backupName}`) ??
    (await foundry.documents.collections.CompendiumCollection.createCompendium({
      name: backupName,
      label: backupTitle,
      type: "Actor",
      ownership,
    }));
  if (!pack || pack.documentName !== "Actor")
    throw new Error("The PC backup compendium is unavailable or has the wrong document type.");
  const createdAt = new Date().toISOString();
  const backups = actors.map((actor) => {
    const data = structuredClone(actor);
    const flags = (data["flags"] ?? {}) as Record<string, Record<string, unknown>>;
    return {
      ...data,
      _id: foundry.utils.randomID(),
      name: `${String(actor["name"] ?? actor._id)} — ${createdAt}`,
      folder: null,
      flags: {
        ...flags,
        [PACKAGE_ID]: {
          ...flags[PACKAGE_ID],
          // A system's create lifecycle can normalize a compendium actor. Preserve the exact
          // original separately as JSON, including embedded IDs, permissions and token data.
          importBackup: { actorId: actor._id, createdAt, source: JSON.stringify(actor) },
        },
      },
    };
  });
  try {
    await pack.configure({ locked: false, ownership });
    const created = await actorClass.createDocuments(backups, {
      pack: pack.collection,
      keepId: true,
      keepEmbeddedIds: true,
      noHook: true,
      ...(game?.system.id === "wfrp4e" ? { skipItems: true } : {}),
      render: false,
      renderSheet: false,
    });
    if (
      created.length !== backups.length ||
      !backups.every((backup) => created.some((actor) => actor.id === backup._id))
    )
      throw new Error("Foundry did not save every PC backup.");
    // A query forces a database read instead of trusting a cached document.
    const saved = await pack.getDocuments({ _id__in: backups.map((backup) => backup._id) });
    for (const backup of backups) {
      const data = saved.find((entry) => entry.id === backup._id)?.toObject();
      const flags = data?.["flags"] as
        Record<string, { importBackup?: { source?: string } }> | undefined;
      if (
        flags?.[PACKAGE_ID]?.importBackup?.source !== backup.flags[PACKAGE_ID]?.importBackup.source
      )
        throw new Error(`Could not verify the saved backup of ${backup.name}.`);
    }
  } finally {
    await pack.configure({ locked: true });
  }
  ui.notifications.info(`${actors.length} PC backups saved in ${backupTitle}.`);
}
