import type {
  CampaignImportBatch,
  CampaignImportOptions,
  CampaignImportPlan,
  CampaignSource,
} from "../../../types/campaign-import";
import { indexSources, selectedFolders } from "./folders";
import { restoreOwnership, validateOwnershipMap } from "./ownership";
import { restoreWorldReferences } from "./references";
import { validateSceneTargets, validateSelection } from "./validation";
import { campaignDocumentTypes } from "./packs";

export { collectOwnershipUserIds } from "./ownership";

function emptyBatch(): CampaignImportBatch {
  return { create: [], update: [], skipped: 0 };
}

/** Prepare every write before the runtime creates or updates any Foundry document. */
export function planCampaignImport(options: CampaignImportOptions): CampaignImportPlan {
  validateSelection(options);
  validateOwnershipMap(options);
  const selected = new Set(options.selectedTypes);
  const available = new Map<string, CampaignSource>();
  const existing = new Map<string, CampaignSource>();
  for (const type of campaignDocumentTypes) {
    indexSources(options.source[type], type);
    for (const document of indexSources(options.existing[type], `existing ${type}`).values()) {
      available.set(`${type}.${document._id}`, document);
      existing.set(`${type}.${document._id}`, document);
    }
    if (selected.has(type)) {
      for (const document of options.source[type]) {
        const target = `${type}.${document._id}`;
        if (options.mode === "update" || !available.has(target)) available.set(target, document);
      }
    }
  }
  validateSceneTargets(options, available);
  const folders = selectedFolders(options);
  const existingFolders = indexSources(options.existing.Folder, "existing Folder");
  const dropped = new Set<string>();
  const plan: CampaignImportPlan = {
    documents: {
      Actor: emptyBatch(),
      Item: emptyBatch(),
      JournalEntry: emptyBatch(),
      Scene: emptyBatch(),
      Macro: emptyBatch(),
      RollTable: emptyBatch(),
    },
    folders: emptyBatch(),
    counts: { create: 0, update: 0, skipped: 0 },
    droppedOwnershipIds: [],
  };

  function add(
    source: CampaignSource,
    current: CampaignSource | undefined,
    batch: CampaignImportBatch,
  ): void {
    if (current && options.mode !== "update") {
      batch.skipped += 1;
      return;
    }
    const linked = restoreWorldReferences(source, available, options.packageId, options.packs);
    const data = restoreOwnership(linked, current, options, dropped) as CampaignSource;
    (current ? batch.update : batch.create).push(data);
  }

  for (const folder of folders) add(folder, existingFolders.get(folder._id), plan.folders);
  for (const type of campaignDocumentTypes) {
    if (!selected.has(type)) continue;
    const batch = plan.documents[type];
    for (const source of options.source[type]) {
      const current = existing.get(`${type}.${source._id}`);
      // Importing content must not switch or deactivate the world's current scene.
      const data = type === "Scene" ? { ...source, active: current?.["active"] === true } : source;
      add(data, current, batch);
    }
    plan.counts.create += batch.create.length;
    plan.counts.update += batch.update.length;
    plan.counts.skipped += batch.skipped;
  }
  plan.droppedOwnershipIds = [...dropped].sort();
  return plan;
}
