import type { CurveStep } from "../../../types/xp-curve/Configuration";
import type {
  CurveGraphBounds,
  CurveGraphProjection,
  XpGraphPoint,
} from "../../../types/xp-curve/Graph";
import type { XpActorChoice, XpAward, XpCurveParameters } from "../../../types/xp-curve/XpCurve";
import {
  calculateAwardForGap,
  calculateCatchUpValue,
  calculateRecipientDecay,
  calculateXpAwardPlan,
  normalizeXpCurveParameters,
} from "./calculate";

export const graphWidth = 560;
export const graphHeight = 270;
export const plotLeft = 68;
export const plotTop = 24;
export const plotWidth = 472;
export const plotHeight = 192;

const DEFAULT_X_MAXIMUM = 5000;
const DEFAULT_BONUS_MAXIMUM = 1000;

function xpAxisMaximum(extent: number, baseline: number, previous = baseline): number {
  let maximum = Math.max(baseline, previous);
  // Reaching the edge must allow another drag beyond it. Use a lower threshold on
  // the way back so moving just below that same value does not toggle the scale.
  while (extent >= maximum && Number.isFinite(maximum * 2)) maximum *= 2;
  while (maximum > baseline && extent <= maximum * 0.4) maximum /= 2;
  return maximum;
}

function chooseBounds(
  step: CurveStep,
  awards: XpAward[],
  parameters: XpCurveParameters,
  previous?: CurveGraphBounds,
): CurveGraphBounds {
  const showGap = step === "catchUpRate" || step === "curveExponent";
  let extent = 0;
  if (step === "scalePivot") extent = parameters.scalePivot;
  if (step === "scaleExponent") extent = parameters.scalePivot * 2;
  for (const award of awards) extent = Math.max(extent, showGap ? award.gap : award.beforeXp);
  const maximumX = xpAxisMaximum(extent, DEFAULT_X_MAXIMUM, previous?.maximumX);

  let maximumY = 1; // Weakening is always displayed from 0% to 100%.
  if (showGap || step === "maximumAward" || step === "review") {
    const peak = showGap ? calculateCatchUpValue(maximumX, parameters) : parameters.maximumAward;
    maximumY = xpAxisMaximum(peak, DEFAULT_BONUS_MAXIMUM, previous?.maximumY);
  }
  return { maximumX, maximumY, handleGap: maximumX * 0.75 };
}

export function buildCurveGraph(
  step: CurveStep,
  actors: XpActorChoice[],
  parameters: XpCurveParameters,
  scale: { previous?: CurveGraphBounds | undefined; frozen?: CurveGraphBounds | undefined } = {},
): CurveGraphProjection {
  parameters = normalizeXpCurveParameters(parameters);
  const plan = calculateXpAwardPlan(actors, parameters);
  const weakening = step === "scalePivot" || step === "scaleExponent";
  const final = step === "maximumAward" || step === "review";
  const bounds = scale.frozen ?? chooseBounds(step, plan.awards, parameters, scale.previous);
  const point = (x: number, y: number) => ({
    x: projectGraphX(x, bounds.maximumX),
    y: projectGraphY(y, bounds.maximumY),
  });
  const rates = final
    ? [...new Set(actors.map((actor) => actor.xpPercent ?? 100))].filter((rate) => rate > 0)
    : [100];
  const series = (rates.length ? rates : [100]).map((rate) => ({
    label: final ? `${rate}% category rate` : weakening ? "Catch-up strength" : "Initial curve XP",
    points: Array.from({ length: 61 }, (_, index) => {
      const x = (index / 60) * bounds.maximumX;
      const y = weakening
        ? calculateRecipientDecay(x, parameters)
        : final
          ? calculateAwardForGap(Math.max(0, plan.highestXp - x), x, parameters, rate / 100)
          : calculateCatchUpValue(x, parameters);
      const projected = point(x, y);
      return `${projected.x.toFixed(1)},${projected.y.toFixed(1)}`;
    }).join(" "),
  }));
  const markers = plan.awards.map((award, index) => ({
    ...point(
      weakening || final ? award.beforeXp : award.gap,
      weakening ? award.decayMultiplier : final ? award.award : award.catchUpValue,
    ),
    actorId: award.actorId,
    index: index + 1,
    label: `${award.actorName}: ${award.beforeXp} total XP, ${award.gap} XP behind; +${award.award} final curve XP`,
  }));
  const handle =
    step === "scalePivot"
      ? point(parameters.scalePivot, 1)
      : step === "scaleExponent"
        ? point(
            parameters.scalePivot * 2,
            calculateRecipientDecay(parameters.scalePivot * 2, parameters),
          )
        : step === "maximumAward"
          ? point(bounds.maximumX * 0.5, parameters.maximumAward)
          : point(bounds.handleGap, calculateCatchUpValue(bounds.handleGap, parameters));
  return {
    bounds,
    handle,
    series,
    markers,
    weakening,
    title: weakening
      ? "How much catch-up help remains"
      : final
        ? "Final curve XP at the current Party leader’s XP"
        : "Initial help before weakening and category rates",
    xLabel: weakening || final ? "Character total XP" : "XP gap below the Party leader",
    yLabel: weakening ? "Help remaining" : final ? "Final bonus XP" : "Initial bonus XP",
  };
}

export function curveValueFromPointer(
  step: Exclude<CurveStep, "review">,
  point: XpGraphPoint,
  bounds: CurveGraphBounds,
  parameters: XpCurveParameters,
): number {
  const x = Math.max(0, Math.min(1, (point.x - plotLeft) / plotWidth)) * bounds.maximumX;
  const y = Math.max(0, Math.min(1, 1 - (point.y - plotTop) / plotHeight)) * bounds.maximumY;
  if (step === "scalePivot") return Math.max(1, Math.min(1000000, Math.round(x)));
  if (step === "maximumAward") return Math.min(100000, Math.round(y));
  if (step === "scaleExponent")
    return round(Math.max(0, Math.min(2, Math.log(Math.max(0.25, y)) / Math.log(0.5))));
  if (step === "catchUpRate")
    return round(Math.min(1000, y / (10 * (bounds.handleGap / 1000) ** parameters.curveExponent)));
  if (parameters.catchUpRate === 0) return parameters.curveExponent;
  return round(
    Math.max(
      0.1,
      Math.min(
        5,
        Math.log(Math.max(0.001, y) / (parameters.catchUpRate * 10)) /
          Math.log(bounds.handleGap / 1000),
      ),
    ),
  );
}

export function projectGraphX(value: number, maximum: number): number {
  return plotLeft + (value / Math.max(1, maximum)) * plotWidth;
}
export function projectGraphY(value: number, maximum: number): number {
  return plotTop + (1 - value / Math.max(0.001, maximum)) * plotHeight;
}
function round(value: number): number {
  return Math.round(value * 100) / 100;
}
