export async function confirmUnsavedPartyChanges(
  zones = false,
): Promise<"save" | "discard" | null> {
  const decision = await foundry.applications.api.DialogV2.wait<string>({
    window: { title: zones ? "Unapplied zone changes" : "Unsaved party changes" },
    modal: true,
    rejectClose: false,
    content: zones
      ? "<p>Apply your zone changes to the party draft before closing?</p>"
      : "<p>Save your changes to the party before closing?</p>",
    buttons: [
      { action: "save", label: zones ? "Apply" : "Save", icon: "fa-solid fa-floppy-disk" },
      { action: "discard", label: "Discard", icon: "fa-solid fa-trash" },
      { action: "cancel", label: "Keep editing", icon: "fa-solid fa-pen", default: true },
    ],
  });
  return decision === "save" || decision === "discard" ? decision : null;
}
