import { PACKAGE_TITLE } from "../constants";
import { registerPackageApi } from "../foundry/api/register-package-api";
import { registerToolkitHooks } from "./register-toolkit";
import { registerCompendiumSidebarSetting } from "../foundry/compendiums/settings";
import { tidyCompendiumSidebarIfEnabled } from "../foundry/compendiums/tidy";
import { registerImportedContentHooks } from "../hooks/imported-content";
import { addCampaignImportButton } from "../foundry/importer/button";
import { registerCampaignImportMenu } from "../foundry/importer/settings";
import {
  addCampaignSettingsImportButton,
  registerCampaignSettingsMenus,
} from "../foundry/settings/menu";

export function registerModuleHooks(): void {
  registerToolkitHooks();
  Hooks.once("init", registerPackageApi);
  if (import.meta.env.CAMPAIGN_WORLD_MODULE) {
    Hooks.once("init", registerCampaignImportMenu);
    Hooks.once("init", registerCampaignSettingsMenus);
    Hooks.on("renderCompendiumDirectory", addCampaignImportButton);
    Hooks.on("renderSettings", addCampaignSettingsImportButton);
  }
  Hooks.once("setup", registerCompendiumSidebarSetting);
  registerImportedContentHooks();
  Hooks.once("ready", async () => {
    try {
      await tidyCompendiumSidebarIfEnabled();
    } catch (error) {
      console.error("Compendium sidebar tidy-up failed.", error);
      ui.notifications.error(
        `${PACKAGE_TITLE}: Compendium cleanup failed and may be incomplete. See the console for details.`,
        { permanent: true, console: false },
      );
    }
  });
}
