import type {
  CampaignContent,
  CampaignDocumentType,
  CampaignSource,
} from "../../../types/campaign-import";
import { isRecord } from "../../functions/importer/references";
import { PACKAGE_ID } from "../../constants";
import type { ImportDocument } from "../../../types/foundry-importer";
import definitions from "../../../campaign/packs.json";
import {
  campaignPacks,
  campaignDocumentTypes,
  emptyCampaignContent,
} from "../../functions/importer/packs";

export const CAMPAIGN_PACKS = /* @__PURE__ */ campaignPacks(definitions);
export const CAMPAIGN_TYPES = /* @__PURE__ */ campaignDocumentTypes.filter((type) =>
  CAMPAIGN_PACKS.some((pack) => pack.type === type),
);

function validatedSource(document: ImportDocument): CampaignSource {
  document.validate({ strict: true, fallback: false, dropInvalidEmbedded: false });
  return document.toObject();
}

export function requireCampaignGM() {
  if (!game?.user.isGM) throw new Error("Only a GM can import campaign content.");
  const systems = [...(game.modules.get(PACKAGE_ID)?.relationships?.systems ?? [])];
  if (systems.length && !systems.some(({ id }) => id === game.system.id))
    throw new Error(
      `This campaign requires one of these systems: ${systems.map(({ id }) => id).join(", ")}.`,
    );
  return game;
}

export async function loadCampaignContent(): Promise<CampaignContent> {
  requireCampaignGM();
  const source = emptyCampaignContent();
  for (const { id, type } of CAMPAIGN_PACKS) {
    const packId = `${PACKAGE_ID}.${id}`;
    const pack = game?.packs.get(packId);
    if (!pack || pack.documentName !== type)
      throw new Error(`Campaign compendium is missing or has the wrong type: ${packId}.`);
    const documents = await pack.getDocuments();
    source[type].push(
      ...documents.map((document) => {
        const data = validatedSource(document);
        const stats = data["_stats"] as Record<string, unknown> | undefined;
        return {
          ...data,
          _stats: { ...stats, compendiumSource: `Compendium.${packId}.${type}.${document.id}` },
        };
      }),
    );
    source.Folder.push(...pack.folders.contents.map(validatedSource));
  }
  return source;
}

function sceneJournalIds(source: CampaignContent): string[] {
  return source.Scene.flatMap((scene) => {
    const notes = scene["notes"];
    return Array.isArray(notes)
      ? notes.flatMap((note) =>
          isRecord(note) && typeof note["entryId"] === "string" ? [note["entryId"]] : [],
        )
      : [];
  });
}

export function snapshotCampaignWorld(source: CampaignContent): CampaignContent {
  const existing = emptyCampaignContent();
  for (const type of [...campaignDocumentTypes, "Folder"] as const) {
    const ids = new Set(source[type].map((doc) => doc._id));
    if (type === "JournalEntry") sceneJournalIds(source).forEach((id) => ids.add(id));
    existing[type] = (game?.collections.get(type)?.contents ?? []).map((doc) =>
      type === "Folder" || ids.has(doc.id) ? doc.toObject() : { _id: doc.id },
    );
  }
  return existing;
}

export function selectedWorldSignature(
  source: CampaignContent,
  existing: CampaignContent,
  selectedTypes: CampaignDocumentType[],
): string {
  const targets: Record<string, CampaignSource[]> = {};
  const types = new Set<CampaignDocumentType | "Folder">([...selectedTypes, "Folder"]);
  if (selectedTypes.includes("Scene")) types.add("JournalEntry");
  for (const type of types) {
    const ids = new Set(source[type].map((doc) => doc._id));
    if (type === "JournalEntry" && selectedTypes.includes("Scene"))
      sceneJournalIds(source).forEach((id) => ids.add(id));
    targets[type] = existing[type].filter((doc) => ids.has(doc._id));
  }
  return JSON.stringify(targets);
}
