import type { Component } from "vue";

import type { XpCurveConsoleActions } from "../../../../types/xp-curve/Console";
import XpCurveConsoleApp from "./XpCurveConsoleApp.vue";
import { openConfigureParty } from "../../configure-party/view/ConfigurePartyApplication";
import { MODULE_ID } from "../../../constants";
import { getXpCurveConsoleInitialization } from "../../../foundry/xp-curve/initialization";
import { applyXpCurveAwards } from "../../../foundry/xp-curve/service";
import { ToolkitVueApplication } from "../../../foundry/apps/ToolkitVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../../../foundry/apps/access";

export class XpCurveConsoleApplication extends ToolkitVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.xpCurveConsole;

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    classes: [MODULE_ID, `${MODULE_ID}-xp-curve-console`],
    id: `${MODULE_ID}-xp-curve-console`,
    position: {
      height: 420,
      width: 500,
    },
    window: {
      icon: "fa-solid fa-chart-line",
      resizable: true,
      title: "Curve XP",
    },
  };

  protected override getVueComponent(): Component {
    return XpCurveConsoleApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    const actions: XpCurveConsoleActions = {
      applyAwards: applyXpCurveAwards,
      onActionComplete: () => {
        void this.close().catch((error: unknown) => {
          console.error(`${MODULE_ID} | Failed to close the Curve XP.`, error);
          ui.notifications.error(
            "XP awards completed, but Drowsy’s WFRP4e Toolkit could not close the console.",
          );
        });
      },
      openParty: () => {
        void openConfigureParty();
      },
      close: () => {
        void this.close();
      },
    };

    return {
      actions,
      initialization: getXpCurveConsoleInitialization(),
    };
  }
}
