import type { FoundryFolder } from "../../../types/folders";
import type { ToolkitMacroSyncPlan } from "../../../types/macros/Sync";
import { MODULE_ID, MODULE_TITLE, WFRP4E_SYSTEM_ID } from "../../constants";
import { planToolkitMacroSync } from "../../functions/macros/sync";
import { isRecord } from "../../functions/records/parse";
import { extractToolkitMacro, TOOLKIT_MACRO_PACK } from "./source";

export const IGNORE_MACRO_PROMPTS_SETTING = "ignoreMacroImportPrompts";

export function registerMacroImportSetting(): void {
  game.settings.register(MODULE_ID, IGNORE_MACRO_PROMPTS_SETTING, {
    name: "Ignore toolkit macro import prompts",
    hint: "Do not ask to import or update toolkit macros at startup. Uncheck to resume checks in this world.",
    config: game.user.isGM,
    default: false,
    scope: "world",
    type: Boolean,
  });
}

async function inspectMacros(): Promise<ToolkitMacroSyncPlan> {
  const pack = game.packs.get(TOOLKIT_MACRO_PACK);
  if (!pack) throw new Error("The toolkit macro compendium is unavailable.");
  const sources = (await pack.getDocuments()).map((macro) => {
    const source = extractToolkitMacro(macro.toObject());
    if (!source) throw new Error(`Invalid bundled macro: ${macro.name}.`);
    return source;
  });
  return planToolkitMacroSync(
    sources,
    Array.from(game.macros).flatMap((macro) => {
      const source = extractToolkitMacro(macro.toObject());
      return source ? [source] : [];
    }),
  );
}

function canPrompt(): boolean {
  return (
    game.ready &&
    game.system.id === WFRP4E_SYSTEM_ID &&
    game.user.isGM &&
    game.user.isActiveGM &&
    game.settings.get(MODULE_ID, IGNORE_MACRO_PROMPTS_SETTING) !== true
  );
}

export async function promptToolkitMacroImport(): Promise<void> {
  if (!canPrompt()) return;
  const plan = await inspectMacros();
  if (!plan.create.length && !plan.update.length) return;
  const choice = await foundry.applications.api.DialogV2.wait({
    window: { title: "Drowsy’s Toolkit Macros" },
    position: { width: 460 },
    content:
      `<p>Your toolkit macros need attention: <strong>${plan.create.length} missing</strong>, ` +
      `<strong>${plan.update.length} to update</strong>.</p>` +
      `<p>Import the latest macros into folders grouped by task. Updating replaces imported macro ` +
      `code, names, and icons while keeping their IDs, hotbar links, and permissions.</p>` +
      `<p>“Don’t Ask Again” disables reminders for this world. Re-enable them in Module Settings.</p>`,
    buttons: [
      { action: "import", label: plan.update.length ? "Import / Update" : "Import Macros" },
      { action: "later", label: "Ask Next Time", default: true },
      { action: "ignore", label: "Don’t Ask Again" },
    ],
    rejectClose: false,
  });
  if (!canPrompt()) return;
  if (choice === "ignore") {
    await game.settings.set(MODULE_ID, IGNORE_MACRO_PROMPTS_SETTING, true);
  } else if (choice === "import") {
    // Recheck after review so an import completed by another client isn't duplicated.
    const latest = await inspectMacros();
    await synchronizeToolkitMacros(latest);
    ui.notifications.info(
      `Toolkit macros: ${latest.create.length} imported, ${latest.update.length} updated.`,
    );
  }
}

async function synchronizeToolkitMacros(plan: ToolkitMacroSyncPlan): Promise<void> {
  if (!plan.create.length && !plan.update.length) return;
  const pack = game.packs.get(TOOLKIT_MACRO_PACK);
  if (!pack) throw new Error("The toolkit macro compendium is unavailable.");
  const folders = [...game.folders].filter((folder) => folder.type === "Macro");
  let root = folders.find((folder) => {
    const flags = folder.flags?.[MODULE_ID];
    return !folder.folder && isRecord(flags) && flags["importedContentRoot"] === true;
  });
  root ??= folders.find((folder) => !folder.folder && folder.name === MODULE_TITLE);
  root ??= await createFolder({
    name: MODULE_TITLE,
    flags: { [MODULE_ID]: { importedContentRoot: true } },
  });
  const destinations = new Map<string, FoundryFolder>([["", root]]);
  async function destination(sourceId: string): Promise<FoundryFolder> {
    const existing = destinations.get(sourceId);
    if (existing) return existing;
    const source = pack!.folders.contents.find((folder) => folder.id === sourceId);
    if (!source) throw new Error(`Bundled macro folder ${sourceId} is unavailable.`);
    const parent = await destination(source.folder?.id ?? "");
    const folder =
      folders.find((folder) => folder.folder?.id === parent.id && folder.name === source.name) ??
      (await createFolder({ name: source.name, folder: parent.id }));
    folders.push(folder);
    destinations.set(sourceId, folder);
    return folder;
  }

  for (const source of plan.create) {
    await game.macros.importFromCompendium(
      pack,
      source.id,
      {
        folder: (await destination(source.folderId)).id,
        [`flags.${MODULE_ID}.macroFolder`]: source.folderId,
      },
      { keepId: false },
    );
  }
  for (const { source, worldId } of plan.update) {
    const macro = Array.from(game.macros).find((macro) => macro.id === worldId);
    if (!macro) throw new Error(`Imported macro ${worldId} disappeared; try again.`);
    await macro.update({
      name: source.name,
      command: source.command,
      img: source.img,
      scope: source.scope,
      type: source.type,
      folder: (await destination(source.folderId)).id,
      [`flags.${MODULE_ID}.macroFolder`]: source.folderId,
    });
  }
}

async function createFolder(data: Record<string, unknown>): Promise<FoundryFolder> {
  const folder = await CONFIG.Folder.documentClass.create({ type: "Macro", sorting: "a", ...data });
  if (!folder) throw new Error(`Could not create macro folder ${String(data["name"])}.`);
  return folder;
}
