import type { XpActorChoice, XpCurveParameters } from "../../../types/xp-curve/XpCurve";
import { calculateFixedXpAwardPlan } from "../xp-award/calculate";
import { calculateXpAwardPlan } from "./calculate";

export interface CurveSessionRow {
  session: number;
  actorId: string;
  actorName: string;
  ordinaryXp: number;
  curveXp: number;
  totalXp: number;
  gap: number;
}

export function simulateCurveSessions(
  actors: XpActorChoice[],
  parameters: XpCurveParameters,
  sessions: number,
  sessionXp: number,
): CurveSessionRow[] {
  if (!Number.isInteger(sessions) || sessions < 1 || sessions > 100)
    throw new Error("Choose between 1 and 100 sessions.");
  if (!Number.isSafeInteger(sessionXp) || sessionXp < 0 || sessionXp > 100000)
    throw new Error("Choose ordinary session XP between 0 and 100,000.");
  let current = actors.map((actor) => ({ ...actor }));
  const rows: CurveSessionRow[] = [];
  for (let session = 1; session <= sessions; session++) {
    const ordinary = calculateFixedXpAwardPlan(current, sessionXp);
    const ordinaryById = new Map(ordinary.awards.map((award) => [award.actorId, award]));
    current = current.map((actor) => ({
      ...actor,
      totalXp: ordinaryById.get(actor.id)?.afterXp ?? actor.totalXp,
    }));
    const curve = calculateXpAwardPlan(current, parameters);
    const curveById = new Map(curve.awards.map((award) => [award.actorId, award]));
    current = current.map((actor) => ({
      ...actor,
      totalXp: curveById.get(actor.id)?.afterXp ?? actor.totalXp,
    }));
    const leaderXp = Math.max(
      0,
      ...current.filter((actor) => actor.categoryId === "party").map((actor) => actor.totalXp),
    );
    for (const actor of current) {
      rows.push({
        session,
        actorId: actor.id,
        actorName: actor.name,
        ordinaryXp: ordinaryById.get(actor.id)?.amount ?? 0,
        curveXp: curveById.get(actor.id)?.award ?? 0,
        totalXp: actor.totalXp,
        gap: Math.max(0, leaderXp - actor.totalXp),
      });
    }
  }
  return rows;
}
