import type { ToolkitApplicationHandle } from "../../../types/module/api/ModuleApi";
import type { PreparedXpAward } from "../../../types/xp-award/XpAward";
import { xpAwardDialogContent, xpRecipientPortraits } from "../../functions/xp-award/dialog";
import { calculateFixedXpAwardPlan } from "../../functions/xp-award/calculate";
import { formatXpAwardDateTime, resolveFixedXpAwardReason } from "../../functions/xp-award/reason";
import { getCurrentSessionReference } from "../session-management/settings/load";
import { getXpAwardSettings } from "./settings/load";
import { prepareXpRecipients } from "./recipients";
import { applyFixedXpAwards } from "./service";
import { MODULE_ID } from "../../constants";

export const openPartyXp = (): Promise<ToolkitApplicationHandle> => openXpDialog("party");
export const openTargetXp = (): Promise<ToolkitApplicationHandle> => openXpDialog("targets");

async function openXpDialog(mode: PreparedXpAward["mode"]): Promise<ToolkitApplicationHandle> {
  const actors = await prepareXpRecipients(mode);
  const settings = getXpAwardSettings();
  const awardedAt = new Date().toISOString();
  const sessionReference = getCurrentSessionReference();
  const context = {
    date: awardedAt.slice(0, 10),
    datetime: formatXpAwardDateTime(awardedAt),
    session: sessionReference,
  };
  let busy = false;
  const dialog: foundry.applications.api.DialogV2 = new foundry.applications.api.DialogV2({
    classes: ["drowsy-xp-award"],
    window: { title: mode === "party" ? "Party XP" : "Target XP" },
    position: { width: 420 },
    form: { closeOnSubmit: false },
    content: xpAwardDialogContent(settings.defaultAmount, settings.defaultReason),
    buttons: [
      { action: "cancel", label: "Cancel", type: "button", callback: () => dialog.close() },
      {
        action: "award",
        label: "Submit",
        default: true,
        callback: async () => {
          if (busy) return;
          const values = read();
          if (!values || !Number.isSafeInteger(values.amount) || values.amount === 0) return;
          busy = true;
          const fields = dialog.element.querySelector<HTMLFieldSetElement>("fieldset")!;
          fields.disabled = true;
          const error = dialog.element.querySelector<HTMLElement>(".xp-error")!;
          error.hidden = true;
          try {
            await applyFixedXpAwards({
              ...settings,
              defaultAmount: values.amount,
              defaultReason: values.reason,
              actorIds: actors.map((actor) => actor.id),
              prepared: {
                mode,
                actors,
                awardedAt,
                sessionReference,
                reason: resolve(values.reason),
              },
            });
            await dialog.close();
          } catch (cause) {
            console.error(`${MODULE_ID} | XP award failed.`, cause);
            error.textContent =
              cause instanceof Error ? cause.message : "The XP award could not be completed.";
            error.hidden = false;
          } finally {
            busy = false;
            fields.disabled = false;
          }
        },
      },
    ],
  });
  function resolve(reason: string): string {
    return resolveFixedXpAwardReason(reason, context, settings.includeTimestampInReason);
  }
  function read(): { amount: number; reason: string } | undefined {
    const form = dialog.element.querySelector("form");
    if (!form) return;
    const data = new FormData(form);
    const amount = String(data.get("amount") ?? "");
    return {
      amount: amount.trim() ? Number(amount) : NaN,
      reason: String(data.get("reason") ?? ""),
    };
  }
  function update(): void {
    const values = read();
    if (!values) return;
    const valid = Number.isSafeInteger(values.amount) && values.amount !== 0;
    const preview = dialog.element.querySelector<HTMLElement>("[data-xp-reason]")!;
    preview.textContent = resolve(values.reason) || "No reason";
    const portraits = dialog.element.querySelector<HTMLElement>(".xp-recipients")!;
    const submit = dialog.element.querySelector<HTMLButtonElement>('[data-action="award"]')!;
    try {
      const amount = valid ? values.amount : 0;
      portraits.innerHTML = xpRecipientPortraits(actors, amount);
      const changes = calculateFixedXpAwardPlan(actors, amount).awards.some(
        (award) => award.amount !== 0,
      );
      submit.disabled = !valid || !changes || busy;
    } catch {
      portraits.replaceChildren();
      submit.disabled = true;
    }
  }
  dialog.addEventListener("render", () => {
    dialog.element.querySelector("form")?.addEventListener("input", update);
    update();
  });
  await dialog.render(true);
  return dialog;
}
