import type { XpActorChoice } from "../../../types/xp-curve/XpCurve";
import { calculateFixedXpAwardPlan } from "./calculate";
import { escapeHtml } from "../xp-curve/reason";

export function xpRecipientPortraits(actors: XpActorChoice[], amount: number): string {
  const plan = calculateFixedXpAwardPlan(actors, amount);
  return plan.awards
    .filter((award) => award.amount !== 0)
    .map((award) => {
      const actor = actors.find((entry) => entry.id === award.actorId)!;
      const label = `${actor.name} — ${award.amount > 0 ? "+" : ""}${award.amount} XP`;
      return `<span class="xp-recipient" tabindex="0" data-recipient-id="${escapeHtml(actor.id)}" title="${escapeHtml(label)}" aria-label="${escapeHtml(label)}" data-tooltip="${escapeHtml(escapeHtml(label))}"><img src="${escapeHtml(actor.img || "icons/svg/mystery-man.svg")}" alt="" width="36" height="36"></span>`;
    })
    .join("");
}

export function xpAwardDialogContent(amount: number, reason: string): string {
  return `<fieldset class="xp-inputs"><label class="form-group"><span>XP amount</span><input type="number" name="amount" value="${amount}" step="1" required autofocus></label><label class="form-group stacked"><span>Reason</span><input type="text" name="reason" value="${escapeHtml(reason)}" autocomplete="off"></label></fieldset><div class="xp-log-preview"><small>Log entry</small><p data-xp-reason></p></div><div class="xp-recipients" aria-label="XP recipients"></div><p class="xp-error" role="alert" hidden></p>`;
}
