import type { ToolkitApplicationHandle } from "../../../../types/module/api/ModuleApi";
import { XpCurveConfiguratorApplication } from "./XpCurveConfiguratorApplication";

export async function openXpCurveConfigurator(): Promise<ToolkitApplicationHandle> {
  const application = new XpCurveConfiguratorApplication();
  await application.render(true);
  return application;
}
