import {
  calculateXpAwardPlan,
  normalizeXpCurveParameters,
} from "../../functions/xp-curve/calculate";
import { escapeHtml } from "../../functions/xp-curve/reason";
import type { XpAwardRequest, XpAwardResult } from "../../../types/xp-curve/XpCurve";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";
import { getCurveRoster } from "./roster";
import { getXpCurveSettings } from "./settings/load";

let awarding = false;

export async function applyXpCurveAwards(request: XpAwardRequest): Promise<XpAwardResult> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.xpCurveConsole);
  if (awarding) throw new Error("A Curve XP award is already in progress.");
  awarding = true;
  try {
    return await awardPreparedCurve(request);
  } finally {
    awarding = false;
  }
}

async function awardPreparedCurve(request: XpAwardRequest): Promise<XpAwardResult> {
  const { actors, runtimes, rosterIssue } = getCurveRoster();
  if (rosterIssue) throw new Error(rosterIssue);
  const parameters = normalizeXpCurveParameters(getXpCurveSettings().parameters);
  const expected = new Map(request.actors.map((actor) => [actor.id, actor]));
  const changed =
    expected.size !== request.actors.length ||
    expected.size !== actors.length ||
    actors.some((actor) => {
      const before = expected.get(actor.id);
      return (
        !before ||
        before.totalXp !== actor.totalXp ||
        before.xpPercent !== actor.xpPercent ||
        before.categoryId !== actor.categoryId
      );
    });
  if (
    changed ||
    JSON.stringify(parameters) !== JSON.stringify(normalizeXpCurveParameters(request.parameters))
  ) {
    throw new Error(
      "XP, the party roster, or curve settings changed after this preview. No XP was applied. Check any earlier partial award, then reopen Curve XP to review fresh amounts.",
    );
  }
  const plan = calculateXpAwardPlan(actors, parameters);
  if (!plan.leader || plan.totalAward < 1)
    throw new Error("This curve produces no XP awards for the configured party.");
  const reason = request.reason.trim();
  const applied: string[] = [];
  for (const [index, runtime] of runtimes.entries()) {
    const award = plan.awards[index]!;
    if (award.award === 0) continue;
    try {
      await runtime.awardExperience(award.award, reason);
      applied.push(award.actorName);
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error);
      throw new Error(
        `Could not award XP to ${award.actorName}. ${detail}${applied.length ? ` XP was already applied to ${applied.join(", ")}.` : ""} Check the actors’ XP logs before trying again.`,
        { cause: error },
      );
    }
  }
  const result = { ...plan, reason };
  // Completed awards stay successful even when the chat report fails.
  try {
    await postXpAwardSummary(result);
  } catch (error) {
    console.error("Drowsy's Toolkit | Curve XP applied, but chat summary failed.", error);
    ui.notifications.error(
      "Curve XP was applied, but the chat summary failed. Do not award it again.",
    );
  }
  ui.notifications.info(
    `Awarded ${result.totalAward} total curve XP across ${applied.length} characters.`,
  );
  return result;
}

async function postXpAwardSummary(result: XpAwardResult): Promise<void> {
  const rows = result.awards
    .filter((award) => award.award > 0)
    .map(
      (award) =>
        `<li><strong>${escapeHtml(award.actorName)}</strong>: +${award.award} XP (${award.beforeXp} → ${award.afterXp})</li>`,
    )
    .join("");
  const content = `<h2>Curve XP</h2><p>${escapeHtml(result.reason)}</p><p>Party leader: ${escapeHtml(result.leader?.name ?? "")} (${result.highestXp} XP)</p><ul>${rows}</ul>`;
  await ChatMessage.create(
    game.wfrp4e.utility.chatDataSetup(content, "gmroll", false, {
      alias: "Drowsy’s WFRP4e Toolkit",
    }),
  );
}
