import type { PartyConfiguration } from "../../../types/party/Party";
import { isRecord } from "../records/parse";

export function createPartyConfiguration(assignedActorIds: string[]): PartyConfiguration {
  return {
    version: 1,
    categories: [
      { id: "party", name: "Party", xpPercent: 100, actorIds: [...new Set(assignedActorIds)] },
      { id: "companions", name: "Companions", xpPercent: 50, actorIds: [] },
    ],
  };
}

export function validatePartyConfiguration(value: unknown): PartyConfiguration {
  if (!isRecord(value) || value["version"] !== 1 || !Array.isArray(value["categories"]))
    throw new Error("The saved party configuration is unreadable or from an unsupported version.");
  const categoryIds = new Set<string>();
  const actorIds = new Set<string>();
  const categories = value["categories"].map((entry: unknown) => {
    if (
      !isRecord(entry) ||
      typeof entry["id"] !== "string" ||
      !entry["id"].trim() ||
      typeof entry["name"] !== "string" ||
      !entry["name"].trim() ||
      typeof entry["xpPercent"] !== "number" ||
      !Number.isFinite(entry["xpPercent"]) ||
      entry["xpPercent"] < 0 ||
      !Array.isArray(entry["actorIds"])
    )
      throw new Error("Every party category needs a name and a non-negative XP percentage.");
    const id = entry["id"];
    if (categoryIds.has(id)) throw new Error("Party category IDs must be unique.");
    categoryIds.add(id);
    const members = entry["actorIds"].map((member: unknown) => {
      if (typeof member !== "string" || !member.trim())
        throw new Error("The party contains an invalid actor reference.");
      if (actorIds.has(member)) throw new Error("An actor can belong to only one party category.");
      actorIds.add(member);
      return member;
    });
    return { id, name: entry["name"].trim(), xpPercent: entry["xpPercent"], actorIds: members };
  });
  if (!categoryIds.has("party") || !categoryIds.has("companions"))
    throw new Error("The Party and Companions categories are required.");
  return { version: 1, categories };
}

export function parsePartyConfiguration(value: unknown): PartyConfiguration | undefined {
  if (value === "" || value === undefined) return undefined;
  if (typeof value !== "string") throw new Error("The saved party configuration is unreadable.");
  let parsed: unknown;
  try {
    parsed = JSON.parse(value);
  } catch {
    throw new Error("The saved party configuration is unreadable. It has not been overwritten.");
  }
  return validatePartyConfiguration(parsed);
}

export function movePartyActor(
  configuration: PartyConfiguration,
  actorId: string,
  categoryId: string,
): PartyConfiguration {
  if (!configuration.categories.some((category) => category.id === categoryId))
    throw new Error("Choose an available party category.");
  return {
    version: 1,
    categories: configuration.categories.map((category) => ({
      ...category,
      actorIds: [
        ...category.actorIds.filter((id) => id !== actorId),
        ...(category.id === categoryId ? [actorId] : []),
      ],
    })),
  };
}
