import type { XpCurveRoster } from "../../../types/xp-curve/Configuration";
import { getPartyConfiguration } from "../party/configuration";
import { createXpActorRuntime, type XpActorRuntime } from "./actors";

export function getCurveRoster(): XpCurveRoster & { runtimes: XpActorRuntime[] } {
  const runtimes: XpActorRuntime[] = [];
  let rosterIssue: string | undefined;
  for (const zone of getPartyConfiguration().categories) {
    for (const id of zone.actorIds) {
      const actor = game.actors.get(id);
      if (!actor || actor.type !== "character") {
        rosterIssue = `A member of ${zone.name} is missing. Repair the roster in Configure Party.`;
        continue;
      }
      const runtime = createXpActorRuntime(
        actor,
        zone.id === "companions" ? "companion" : "standard",
        true,
        zone.xpPercent,
        zone.name,
      );
      runtime.choice.categoryId = zone.id;
      runtimes.push(runtime);
    }
  }
  if (!runtimes.some(({ choice }) => choice.categoryId === "party")) {
    rosterIssue =
      "Add a character to the Party zone in Configure Party to establish the XP leader.";
  }
  return { actors: runtimes.map(({ choice }) => choice), runtimes, rosterIssue };
}
