<script setup lang="ts">
import { storeToRefs } from "pinia";
import { useXpCurveConfiguratorStore } from "../state/store";
import { CURVE_STEPS } from "../../../functions/xp-curve/setup";
import type {
  CurveDraft,
  XpCurveConfiguratorActions,
  XpCurveConfiguratorInitialization,
} from "../../../../types/xp-curve/Configuration";
import CurveStepGraph from "./curve/CurveStepGraph.vue";
import CurveAwardPreview from "../../shared/view/CurveAwardPreview.vue";
import CurveForecast from "./review/CurveForecast.vue";

const props = defineProps<{
  actions: XpCurveConfiguratorActions;
  initialization: XpCurveConfiguratorInitialization;
  initialDraft?: CurveDraft;
  initialStep?: number;
}>();
const store = useXpCurveConfiguratorStore();
store.initialize(props.initialization, props.actions, props.initialDraft, props.initialStep);
const {
  draft,
  stepIndex,
  step,
  previewActors,
  plan,
  forecast,
  inputError,
  errorMessage,
  statusMessage,
  isWorking,
} = storeToRefs(store);
</script>

<template>
  <form
    class="tw:flex tw:h-full tw:min-h-0 tw:min-w-0 tw:flex-col tw:overflow-hidden tw:bg-base-100! tw:text-base-content!"
    @submit.prevent="step.key === 'review' ? store.saveConfiguration() : store.changeStep(1)"
  >
    <header class="tw:shrink-0 tw:border-b tw:border-base-content/20 tw:p-4">
      <p class="tw:m-0 tw:text-xs">Step {{ stepIndex + 1 }} of {{ CURVE_STEPS.length }}</p>
      <h2 class="tw:my-1 tw:border-0! tw:text-xl">{{ step.title }}</h2>
      <p class="tw:m-0 tw:text-sm">{{ step.guidance }}</p>
    </header>
    <div class="tw:min-h-0 tw:min-w-0 tw:flex-1 tw:overflow-auto tw:p-4">
      <p v-if="errorMessage" class="tw:dui-alert tw:dui-alert-error tw:mb-3" role="alert">
        {{ errorMessage }}
      </p>
      <p v-if="statusMessage" class="tw:mb-3 tw:text-sm" role="status">{{ statusMessage }}</p>
      <div
        class="tw:mb-3 tw:flex tw:flex-wrap tw:items-center tw:gap-2"
        role="group"
        aria-label="Preview actors"
      >
        <span class="tw:text-sm">Show on the curve:</span>
        <button
          class="tw:dui-btn tw:dui-btn-sm"
          :class="{ 'tw:dui-btn-primary': draft.previewMode === 'party' }"
          type="button"
          :aria-pressed="draft.previewMode === 'party'"
          @click="draft.previewMode = 'party'"
        >
          My party
        </button>
        <button
          class="tw:dui-btn tw:dui-btn-sm"
          :class="{ 'tw:dui-btn-primary': draft.previewMode === 'example' }"
          type="button"
          :aria-pressed="draft.previewMode === 'example'"
          @click="draft.previewMode = 'example'"
        >
          Example
        </button>
      </div>
      <p
        v-if="draft.previewMode === 'party' && initialization.rosterIssue"
        class="tw:mb-3 tw:text-sm"
        role="status"
      >
        {{ initialization.rosterIssue }}
        <button class="tw:dui-btn tw:dui-btn-sm" type="button" @click="actions.openParty">
          Configure Party
        </button>
        <button
          class="tw:dui-btn tw:dui-btn-sm"
          type="button"
          :disabled="isWorking"
          @click="store.changeStep(0)"
        >
          Refresh party
        </button>
      </p>
      <fieldset :disabled="isWorking" class="tw:m-0 tw:min-w-0 tw:border-0 tw:p-0">
        <CurveStepGraph
          :actors="previewActors"
          :parameters="draft.parameters"
          :step="step.key"
          @update="(key, value) => (draft.parameters[key] = value)"
        />
        <div
          v-if="step.key !== 'review'"
          class="tw:my-3 tw:flex tw:flex-wrap tw:items-center tw:gap-2"
        >
          <label for="curve-step-value" class="tw:text-sm tw:font-semibold">{{ step.label }}</label>
          <input
            id="curve-step-value"
            v-model.number="draft.parameters[step.key]"
            class="tw:dui-input tw:dui-input-sm tw:w-28"
            type="number"
            :min="step.min"
            :max="step.max"
            step="any"
            required
          />
          <span class="tw:text-sm">{{ step.unit }}</span>
          <span v-if="inputError" class="tw:text-sm tw:text-error" role="alert">{{
            inputError
          }}</span>
        </div>
        <CurveAwardPreview :actors="previewActors" :plan="plan" :numbered="true" />
        <CurveForecast
          v-if="step.key === 'review'"
          v-model:sessions="draft.sessions"
          v-model:session-xp="draft.sessionXp"
          :rows="forecast.rows"
          :error="forecast.error"
          :has-leader="!!plan.leader"
          :example="draft.previewMode === 'example'"
        />
      </fieldset>
    </div>
    <footer
      class="tw:flex tw:shrink-0 tw:flex-wrap tw:items-center tw:justify-between tw:gap-2 tw:border-t tw:border-base-content/20 tw:p-3"
    >
      <button
        class="tw:dui-btn tw:dui-btn-sm tw:dui-btn-ghost"
        type="button"
        :disabled="isWorking"
        @click="store.resetToDefaults"
      >
        <i class="fa-solid fa-arrow-rotate-left" aria-hidden="true" /> Reset to defaults
      </button>
      <div class="tw:flex tw:flex-wrap tw:gap-2">
        <button
          class="tw:dui-btn tw:dui-btn-sm"
          type="button"
          :disabled="isWorking"
          @click="actions.close"
        >
          Cancel
        </button>
        <button
          v-if="stepIndex > 0"
          class="tw:dui-btn tw:dui-btn-sm"
          type="button"
          :disabled="isWorking"
          @click="store.changeStep(-1)"
        >
          Back
        </button>
        <button
          class="tw:dui-btn tw:dui-btn-sm tw:dui-btn-primary"
          type="submit"
          :disabled="isWorking || !!inputError"
        >
          {{
            isWorking ? "Please wait…" : step.key === "review" ? "Save configuration" : "Continue"
          }}
          <i v-if="step.key !== 'review'" class="fa-solid fa-arrow-right" aria-hidden="true" />
        </button>
      </div>
    </footer>
  </form>
</template>
