import type { ToolkitMacroSource, ToolkitMacroSyncPlan } from "../../../types/macros/Sync";

export function planToolkitMacroSync(
  sources: ToolkitMacroSource[],
  world: ToolkitMacroSource[],
): ToolkitMacroSyncPlan {
  const plan: ToolkitMacroSyncPlan = { create: [], update: [] };
  for (const source of sources) {
    const matches = world.filter((macro) => macro.sourceId === source.id);
    if (!matches.length) plan.create.push(source);
    for (const macro of matches) {
      if (
        macro.name !== source.name ||
        macro.command !== source.command ||
        macro.img !== source.img ||
        macro.scope !== source.scope ||
        macro.type !== source.type ||
        macro.importedFolderId !== source.folderId
      ) {
        plan.update.push({ source, worldId: macro.id });
      }
    }
  }
  return plan;
}
