import { parseSettingsPresetSources } from "../../functions/settings-presets/sources";
import { parsePresetMetadata } from "../../functions/settings-presets/metadata";
export const CAMPAIGN_SETTINGS = parseSettingsPresetSources(
  import.meta.glob<unknown>("/src/campaign/settings/*.json", { eager: true, import: "default" }),
);
export const CAMPAIGN_PRESET_METADATA = parsePresetMetadata(
  Object.values(
    import.meta.glob<unknown>("/src/campaign/settings-presets.json", {
      eager: true,
      import: "default",
    }),
  )[0] ?? {},
  Object.keys(CAMPAIGN_SETTINGS),
);
