import type { CampaignPackDefinition, CampaignSource } from "../../../types/campaign-import";

// Native embedded document names differ from their source collection fields.
const embeddedFields: Record<string, Record<string, string>> = {
  Actor: { ActiveEffect: "effects", Item: "items" },
  ActorDelta: { ActiveEffect: "effects", Item: "items" },
  Item: { ActiveEffect: "effects" },
  JournalEntry: { JournalEntryCategory: "categories", JournalEntryPage: "pages" },
  Scene: {
    AmbientLight: "lights",
    AmbientSound: "sounds",
    Drawing: "drawings",
    Note: "notes",
    Region: "regions",
    Level: "levels",
    Tile: "tiles",
    Token: "tokens",
    Wall: "walls",
  },
  RollTable: { TableResult: "results" },
  Region: { RegionBehavior: "behaviors" },
  Token: { ActorDelta: "delta" },
};

export function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function targetExists(source: CampaignSource | undefined, type: string, suffix: string): boolean {
  let current: Record<string, unknown> | undefined = source;
  const parts = suffix.split(".").slice(1);
  for (let index = 0; current && index < parts.length; index += 2) {
    const embeddedType = parts[index]!;
    const field = embeddedFields[type]?.[embeddedType];
    const collection: unknown = field ? current[field] : undefined;
    const candidates = Array.isArray(collection) ? collection : [collection];
    current = candidates.find(
      (entry): entry is Record<string, unknown> =>
        isRecord(entry) && entry["_id"] === parts[index + 1],
    );
    type = embeddedType;
  }
  return current !== undefined;
}

/** Content links resolve to world documents only when every embedded target will exist. */
export function restoreWorldReferences(
  value: unknown,
  available: ReadonlyMap<string, CampaignSource>,
  packageId: string,
  packs: CampaignPackDefinition[],
): unknown {
  const escape = (part: string): string => part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const types = new Map(packs.map(({ id, type }) => [id, type]));
  const campaignUuid = new RegExp(
    `Compendium\\.${escape(packageId)}\\.(${packs.map(({ id }) => escape(id)).join("|")})` +
      `\\.(Actor|Item|JournalEntry|Scene|Macro|RollTable)\\.([A-Za-z0-9_-]+)` +
      `((?:\\.[A-Za-z]+\\.[A-Za-z0-9_-]+)*)`,
    "g",
  );
  function visit(entry: unknown, path: string[] = []): unknown {
    if (path.at(-1) === "_stats" || path.slice(-3).join(".") === "flags.core.sourceId")
      return structuredClone(entry);
    if (typeof entry === "string") {
      return entry.replace(
        campaignUuid,
        (original, pack: string, type: string, id: string, suffix: string) => {
          const target = `${type}.${id}`;
          return types.get(pack) === type && targetExists(available.get(target), type, suffix)
            ? `${target}${suffix}`
            : original;
        },
      );
    }
    if (Array.isArray(entry)) return entry.map((child) => visit(child, path));
    if (!isRecord(entry)) return entry;
    return Object.fromEntries(
      Object.entries(entry).map(([key, child]) => [key, visit(child, [...path, key])]),
    );
  }
  return visit(value);
}
