import { PACKAGE_ID, PACKAGE_TITLE } from "../../constants";

export const KEEP_IMPORTED_CONTENT_TIDY_SETTING = "keepImportedContentTidy";

export function registerImportedContentSetting(onChange: () => void): void {
  game?.settings.register(PACKAGE_ID, KEEP_IMPORTED_CONTENT_TIDY_SETTING, {
    config: game.user.isGM === true,
    default: false,
    hint: "Group this module's imported documents under a module folder in each world directory.",
    name: `Keep ${PACKAGE_TITLE} Imported Content Tidy?`,
    onChange,
    scope: "world",
    type: Boolean,
  });
}
