<script setup lang="ts">
import { graphHeight, graphWidth, plotHeight, plotLeft, plotTop, plotWidth } from "../graphMath";
import type { XpGraphMarker } from "../../../../../../types/xp-curve/Graph";

defineProps<{
  description: string;
  descriptionId: string;
  markers: XpGraphMarker[];
  maximumXLabel: string;
  minimumYLabel: string;
  series: { label: string; points: string }[];
  title: string;
  titleId: string;
  verticalGuideX: number;
  xAxisLabel: string;
  yAxisLabel: string;
  maximumYLabel?: string | undefined;
}>();

const emit = defineEmits<{
  pointercancel: [event: PointerEvent];
  pointermove: [event: PointerEvent];
  pointerup: [event: PointerEvent];
}>();
</script>

<template>
  <svg
    class="tw:block tw:h-auto tw:w-full tw:max-w-[35rem] tw:touch-none tw:[user-select:none]"
    :viewBox="`0 0 ${graphWidth} ${graphHeight}`"
    role="group"
    :aria-labelledby="`${titleId} ${descriptionId}`"
    @pointercancel="emit('pointercancel', $event)"
    @pointermove="emit('pointermove', $event)"
    @pointerup="emit('pointerup', $event)"
  >
    <title :id="titleId">{{ title }}</title>
    <desc :id="descriptionId">{{ description }}</desc>

    <line
      class="tw:text-base-content/25!"
      :x1="plotLeft"
      :x2="plotLeft"
      :y1="plotTop"
      :y2="plotTop + plotHeight"
      stroke="currentColor"
    />
    <line
      class="tw:text-base-content/25!"
      :x1="plotLeft"
      :x2="plotLeft + plotWidth"
      :y1="plotTop + plotHeight"
      :y2="plotTop + plotHeight"
      stroke="currentColor"
    />
    <line
      class="tw:text-base-content/25!"
      :x1="verticalGuideX"
      :x2="verticalGuideX"
      :y1="plotTop"
      :y2="plotTop + plotHeight"
      stroke="currentColor"
      stroke-dasharray="4 5"
    />

    <slot name="guides" />

    <polyline
      v-for="(line, index) in series"
      :key="line.label"
      class="tw:text-secondary!"
      fill="none"
      :points="line.points"
      :stroke-dasharray="index === 0 ? undefined : `${3 + index * 2} 4`"
      stroke="currentColor"
      stroke-linecap="round"
      stroke-linejoin="round"
      stroke-width="3"
    >
      <title>{{ line.label }}</title>
    </polyline>

    <g
      v-for="marker in markers"
      :key="marker.actorId"
      class="tw:text-base-content!"
      :aria-label="marker.label"
      role="img"
      tabindex="0"
    >
      <circle
        class="tw:[r:14px] tw:@min-[28rem]:[r:9px]"
        :cx="marker.x"
        :cy="marker.y"
        fill="currentColor"
        r="9"
      >
        <title>{{ marker.label }}</title>
      </circle>
      <text
        class="tw:text-[17px] tw:text-base-100! tw:@min-[28rem]:text-[9px]"
        :x="marker.x"
        :y="marker.y + 3"
        fill="currentColor"
        font-size="9"
        font-weight="700"
        text-anchor="middle"
      >
        {{ marker.index }}
      </text>
    </g>

    <slot name="handles" />

    <text
      class="tw:text-[18px] tw:text-base-content/65! tw:@min-[28rem]:text-[11px]"
      :x="plotLeft"
      :y="plotTop + plotHeight + 18"
      fill="currentColor"
      font-size="11"
      text-anchor="middle"
    >
      0
    </text>
    <text
      class="tw:text-[18px] tw:text-base-content/65! tw:@min-[28rem]:text-[11px]"
      :x="plotLeft + plotWidth"
      :y="plotTop + plotHeight + 18"
      fill="currentColor"
      font-size="11"
      text-anchor="end"
    >
      {{ maximumXLabel }}
    </text>
    <text
      class="tw:text-[20px] tw:text-base-content/75! tw:@min-[28rem]:text-[12px]"
      :x="plotLeft + plotWidth / 2"
      :y="graphHeight - 8"
      fill="currentColor"
      font-size="12"
      font-weight="600"
      text-anchor="middle"
    >
      {{ xAxisLabel }}
    </text>
    <text
      v-if="maximumYLabel"
      class="tw:text-[18px] tw:text-base-content/65! tw:@min-[28rem]:text-[11px]"
      :x="plotLeft - 10"
      :y="plotTop + 4"
      fill="currentColor"
      font-size="11"
      text-anchor="end"
    >
      {{ maximumYLabel }}
    </text>
    <text
      class="tw:text-[18px] tw:text-base-content/65! tw:@min-[28rem]:text-[11px]"
      :x="plotLeft - 10"
      :y="plotTop + plotHeight + 3"
      fill="currentColor"
      font-size="11"
      text-anchor="end"
    >
      {{ minimumYLabel }}
    </text>
    <text
      class="tw:text-[20px] tw:text-base-content/75! tw:@min-[28rem]:text-[12px]"
      :transform="`rotate(-90 16 ${plotTop + plotHeight / 2})`"
      x="16"
      :y="plotTop + plotHeight / 2"
      fill="currentColor"
      font-size="12"
      font-weight="600"
      text-anchor="middle"
    >
      {{ yAxisLabel }}
    </text>

    <slot name="labels" />
  </svg>
</template>
