import { computed, ref } from "vue";
import { defineStore } from "pinia";
import { calculateXpAwardPlan } from "../../../functions/xp-curve/calculate";
import { resolveXpAwardReason } from "../../../functions/xp-curve/reason";
import type {
  XpCurveConsoleActions,
  XpCurveConsoleInitialization,
  XpReasonContext,
} from "../../../../types/xp-curve/Console";
import {
  DEFAULT_XP_CURVE_PARAMETERS,
  type XpActorChoice,
} from "../../../../types/xp-curve/XpCurve";

export const useXpCurveConsoleStore = defineStore("xp-curve-console", () => {
  const actors = ref<XpActorChoice[]>([]);
  const parameters = ref({ ...DEFAULT_XP_CURVE_PARAMETERS });
  const reason = ref("");
  const rosterIssue = ref<string>();
  const errorMessage = ref<string>();
  const isWorking = ref(false);
  const complete = ref(false);
  let actions: XpCurveConsoleActions;
  let reasonContext: XpReasonContext = { date: "", session: "" };
  const plan = computed(() => calculateXpAwardPlan(actors.value, parameters.value));
  const canApply = computed(
    () =>
      !rosterIssue.value &&
      !!plan.value.leader &&
      plan.value.totalAward > 0 &&
      !isWorking.value &&
      !complete.value,
  );
  const resolvedReason = computed(() => resolveXpAwardReason(reason.value, reasonContext));

  function initialize(data: XpCurveConsoleInitialization, handlers: XpCurveConsoleActions): void {
    actors.value = data.actors.map((actor) => ({ ...actor }));
    parameters.value = { ...data.parameters };
    reason.value = data.defaultReason;
    rosterIssue.value = data.rosterIssue;
    reasonContext = data.reasonContext;
    actions = handlers;
  }

  async function applyAwards(): Promise<void> {
    if (!canApply.value) return;
    isWorking.value = true;
    errorMessage.value = undefined;
    try {
      const result = await actions.applyAwards({
        actors: actors.value.map((actor) => ({ ...actor })),
        parameters: { ...parameters.value },
        reason: resolvedReason.value,
      });
      complete.value = true;
      actions.onActionComplete(result);
    } catch (error) {
      errorMessage.value =
        error instanceof Error ? error.message : "The XP awards could not be completed.";
    } finally {
      isWorking.value = false;
    }
  }
  return {
    actors,
    reason,
    rosterIssue,
    errorMessage,
    isWorking,
    complete,
    plan,
    canApply,
    resolvedReason,
    initialize,
    applyAwards,
  };
});
