import type { CampaignImportOptions, CampaignSource } from "../../../types/campaign-import";

export function indexSources(sources: CampaignSource[], type: string): Map<string, CampaignSource> {
  const indexed = new Map<string, CampaignSource>();
  for (const source of sources) {
    if (!source._id) throw new Error(`${type} source has no ID.`);
    if (indexed.has(source._id)) throw new Error(`Duplicate ${type} source ID: ${source._id}`);
    indexed.set(source._id, source);
  }
  return indexed;
}

/** Include empty selected-type folders and preserve native IDs, flags, and parentage. */
export function selectedFolders(options: CampaignImportOptions): CampaignSource[] {
  const source = indexSources(options.source.Folder, "Folder");
  const existing = indexSources(options.existing.Folder, "existing Folder");
  const ordered: CampaignSource[] = [];
  const visited = new Set<string>();
  const visiting = new Set<string>();

  function visit(id: string, type: string): void {
    const folder = source.get(id) ?? existing.get(id);
    if (!folder) throw new Error(`Missing ${type} folder: ${id}`);
    if (folder["type"] !== type) throw new Error(`Folder ${id} has the wrong type for ${type}.`);
    const current = existing.get(id);
    if (current && current["type"] !== type) {
      throw new Error(`Existing folder ${id} belongs to ${String(current["type"])}, not ${type}.`);
    }
    if (visiting.has(id)) throw new Error(`Folder ancestry contains a cycle at ${id}.`);
    if (visited.has(id)) return;
    visiting.add(id);
    const parent = folder["folder"];
    if (typeof parent === "string" && parent) visit(parent, type);
    visiting.delete(id);
    visited.add(id);
    if (source.has(id)) ordered.push(folder);
  }

  for (const type of new Set(options.selectedTypes)) {
    for (const folder of source.values()) {
      if (folder["type"] === type) visit(folder._id, type);
    }
    for (const document of options.source[type]) {
      const folder = document["folder"];
      if (typeof folder === "string" && folder) visit(folder, type);
    }
  }
  return ordered;
}
