import type { CampaignImportOptions, CampaignSource } from "../../../types/campaign-import";
import { isRecord } from "./references";

import { campaignDocumentTypes, campaignPacks } from "./packs";

export function validateSelection(options: CampaignImportOptions): void {
  if (!options.packageId) throw new Error("Campaign package ID is required.");
  const configuredTypes = new Set(campaignPacks(options.packs).map(({ type }) => type));
  if (!Array.isArray(options.selectedTypes) || options.selectedTypes.length === 0) {
    throw new Error("Select at least one campaign document type to import.");
  }
  const unknown = options.selectedTypes.filter(
    (type) => !campaignDocumentTypes.includes(type) || !configuredTypes.has(type),
  );
  if (unknown.length) throw new Error(`Unknown campaign document type: ${unknown.join(", ")}`);
  if (options.mode !== undefined && options.mode !== "skip" && options.mode !== "update") {
    throw new Error(`Unknown campaign import mode: ${String(options.mode)}`);
  }
}

/** Token and map-note references cannot fall back to compendium UUIDs. */
export function validateSceneTargets(
  options: CampaignImportOptions,
  available: ReadonlyMap<string, CampaignSource>,
): void {
  if (!options.selectedTypes.includes("Scene")) return;
  const existing = new Set(options.existing.Scene.map((scene) => scene._id));
  for (const scene of options.source.Scene) {
    if (existing.has(scene._id) && options.mode !== "update") continue;
    const sceneName = String(scene["name"] ?? scene._id);
    for (const [field, key, type, label] of [
      ["tokens", "actorId", "Actor", "Actors"],
      ["notes", "entryId", "JournalEntry", "Journals"],
    ] as const) {
      const embedded = scene[field];
      if (!Array.isArray(embedded)) continue;
      for (const entry of embedded) {
        if (!isRecord(entry)) continue;
        const id = entry[key];
        if (typeof id !== "string" || !id) continue;
        const target = available.get(`${type}.${id}`);
        const include = options.selectedTypes.includes(type)
          ? `Restore that ${type} or correct its ${field} reference first.`
          : `Include ${label} in this import, or restore that ${type} first.`;
        if (!target)
          throw new Error(`Scene "${sceneName}" references missing ${type} ${id}. ${include}`);
        const pageId = entry["pageId"];
        if (type !== "JournalEntry" || typeof pageId !== "string" || !pageId) continue;
        const pages = target["pages"];
        if (
          !Array.isArray(pages) ||
          !pages.some((page) => isRecord(page) && page["_id"] === pageId)
        )
          throw new Error(
            `Scene "${sceneName}" references missing JournalEntryPage ${id}.${pageId}. ` +
              "Import the journal with that page, or correct the scene note before importing.",
          );
      }
    }
  }
}
