import type {
  CampaignContent,
  CampaignDocumentType,
  CampaignImportOptions,
} from "../../../types/campaign-import";
import { isRecord } from "./references";
import { campaignDocumentTypes } from "./packs";

export function collectOwnershipUserIds(
  source: CampaignContent,
  selectedTypes: CampaignDocumentType[] = campaignDocumentTypes,
): string[] {
  const ids = new Set<string>();
  function visit(value: unknown): void {
    if (Array.isArray(value)) {
      value.forEach(visit);
      return;
    }
    if (!isRecord(value)) return;
    for (const [key, entry] of Object.entries(value)) {
      if (key === "ownership" && isRecord(entry)) {
        for (const id of Object.keys(entry)) if (id !== "default") ids.add(id);
      } else visit(entry);
    }
  }
  for (const type of selectedTypes) visit(source[type]);
  return [...ids].sort();
}

export function validateOwnershipMap(options: CampaignImportOptions): void {
  for (const [sourceId, targetId] of Object.entries(options.ownershipMap ?? {})) {
    if (targetId !== null && !options.destinationUserIds.includes(targetId)) {
      throw new Error(`Ownership mapping for ${sourceId} targets an unavailable user: ${targetId}`);
    }
  }
}

function mapOwnership(
  ownership: Record<string, unknown>,
  options: CampaignImportOptions,
  dropped: Set<string>,
): Record<string, unknown> {
  const mapped: Record<string, unknown> = {};
  for (const [id, permission] of Object.entries(ownership)) {
    if (id === "default") {
      mapped[id] = permission;
      continue;
    }
    const target = Object.hasOwn(options.ownershipMap ?? {}, id)
      ? options.ownershipMap?.[id]
      : options.destinationUserIds.includes(id)
        ? id
        : null;
    if (!target) {
      dropped.add(id);
      continue;
    }
    // Several source accounts may explicitly map to one destination account.
    const previous = mapped[target];
    mapped[target] =
      typeof previous === "number" && typeof permission === "number"
        ? Math.max(previous, permission)
        : permission;
  }
  return mapped;
}

/** Existing world ownership wins, including embedded documents matched by their IDs. */
export function restoreOwnership(
  source: unknown,
  existing: unknown,
  options: CampaignImportOptions,
  dropped: Set<string>,
): unknown {
  if (Array.isArray(source)) {
    const byId = new Map(
      (Array.isArray(existing) ? existing : [])
        .filter((entry) => isRecord(entry) && typeof entry["_id"] === "string")
        .map((entry) => [entry["_id"], entry]),
    );
    return source.map((entry) =>
      restoreOwnership(
        entry,
        isRecord(entry) ? byId.get(entry["_id"]) : undefined,
        options,
        dropped,
      ),
    );
  }
  if (!isRecord(source)) return source;
  const current = isRecord(existing) ? existing : undefined;
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(source)) {
    if (key === "ownership" && isRecord(value)) {
      if (current) {
        if (Object.hasOwn(current, key)) result[key] = structuredClone(current[key]);
      } else result[key] = mapOwnership(value, options, dropped);
    } else result[key] = restoreOwnership(value, current?.[key], options, dropped);
  }
  if (current && Object.hasOwn(current, "ownership")) {
    result["ownership"] = structuredClone(current["ownership"]);
  }
  return result;
}
