import { defineStore } from "pinia";
import { computed, ref } from "vue";
import type { PartyConfiguration, PartyZoneActions } from "../../../../types/party/Party";
import { validatePartyConfiguration } from "../../../functions/party/configuration";

export const usePartyZonesStore = defineStore("party-zones", () => {
  const configuration = ref<PartyConfiguration>({ version: 1, categories: [] });
  const applied = ref("");
  const isDirty = computed(() => JSON.stringify(configuration.value) !== applied.value);
  const busy = ref(false),
    error = ref("");
  let actions: PartyZoneActions;
  function initialize(value: PartyConfiguration, callbacks: PartyZoneActions): void {
    configuration.value = structuredClone(value);
    actions = callbacks;
    applied.value = JSON.stringify(configuration.value);
  }
  function add(): void {
    configuration.value.categories.push({
      id: crypto.randomUUID(),
      name: "New zone",
      xpPercent: 100,
      actorIds: [],
    });
  }
  async function remove(id: string): Promise<void> {
    if (id === "party" || id === "companions") return;
    await run(async () => {
      const category = configuration.value.categories.find((entry) => entry.id === id)!;
      if (await actions.remove(category))
        configuration.value.categories = configuration.value.categories.filter(
          (entry) => entry.id !== id,
        );
    });
  }
  async function reset(): Promise<void> {
    await run(async () => {
      const next = await actions.reset();
      if (next) configuration.value = next;
    });
  }
  async function apply(): Promise<void> {
    if (await run(commit)) actions.close();
  }
  async function commit(): Promise<void> {
    actions.apply(validatePartyConfiguration(configuration.value));
    applied.value = JSON.stringify(configuration.value);
  }
  async function canClose(): Promise<boolean> {
    if (busy.value) return false;
    if (!isDirty.value) return true;
    let close = false;
    const success = await run(async () => {
      const decision = await actions.confirmClose();
      if (decision === "save") await commit();
      close = decision === "save" || decision === "discard";
    });
    return success && close;
  }
  async function run(operation: () => Promise<void>): Promise<boolean> {
    if (busy.value) return false;
    busy.value = true;
    error.value = "";
    try {
      await operation();
      return true;
    } catch (cause) {
      error.value = cause instanceof Error ? cause.message : "Could not configure party zones.";
      return false;
    } finally {
      busy.value = false;
    }
  }
  return {
    configuration,
    busy,
    isDirty,
    canClose,
    error,
    initialize,
    add,
    remove,
    reset,
    apply,
    cancel: () => actions.close(),
  };
});
