import type { CampaignImportPlan, CampaignSource } from "../../../types/campaign-import";
import type { CampaignImportResult } from "../../../types/api/CampaignImporter";
import type { ImportDocument } from "../../../types/foundry-importer";
import { requireCampaignGM } from "./content";
import { campaignDocumentTypes } from "../../functions/importer/packs";
import { actorUpdateOptions } from "./system";

export async function executeCampaignImport(
  plan: CampaignImportPlan,
  playerCharacters: CampaignSource[] = [],
): Promise<CampaignImportResult> {
  requireCampaignGM();
  const result: CampaignImportResult = {
    created: 0,
    updated: 0,
    skipped: plan.counts.skipped,
    foldersCreated: 0,
    foldersUpdated: 0,
  };
  const imported: ImportDocument[] = [];
  const originals = new Map(playerCharacters.map((actor) => [actor._id, JSON.stringify(actor)]));
  function record(documents: ImportDocument[], id: string): void {
    if (documents.length !== 1 || documents[0]?.id !== id)
      throw new Error(`Foundry did not save document ${id}.`);
    imported.push(...documents);
  }
  try {
    // Folders are already ordered parent-first by the pure planner.
    const folderClass = game?.collections.get("Folder")?.documentClass;
    if (!folderClass) throw new Error("Foundry's folder collection is unavailable.");
    for (const folder of plan.folders.create) {
      record(
        await folderClass.createDocuments([folder], { keepId: true, render: false }),
        folder._id,
      );
      result.foldersCreated += 1;
    }
    for (const folder of plan.folders.update) {
      record(
        await folderClass.updateDocuments([folder], {
          diff: false,
          recursive: false,
          render: false,
        }),
        folder._id,
      );
      result.foldersUpdated += 1;
    }
    for (const type of campaignDocumentTypes) {
      if (!plan.documents[type].create.length && !plan.documents[type].update.length) continue;
      const cls = game?.collections.get(type)?.documentClass;
      if (!cls) throw new Error(`Foundry's ${type} collection is unavailable.`);
      for (const data of plan.documents[type].create) {
        record(
          await cls.createDocuments([data], { keepId: true, render: false, renderSheet: false }),
          data._id,
        );
        result.created += 1;
      }
      for (const data of plan.documents[type].update) {
        if (type === "Actor" && originals.has(data._id)) {
          const current = game?.collections.get("Actor")?.get(data._id)?.toObject();
          if (JSON.stringify(current) !== originals.get(data._id))
            throw new Error(
              `Player Character ${String(data["name"] ?? data._id)} changed during import. Its update was stopped.`,
            );
        }
        record(
          await cls.updateDocuments([data], {
            diff: false,
            recursive: false,
            noHook: true,
            render: false,
            ...(type === "Actor" ? actorUpdateOptions() : {}),
          }),
          data._id,
        );
        result.updated += 1;
      }
    }
    // Resolve cross-document links after every selected collection exists.
    imported.forEach((document) => document.reset());
    await ui.sidebar.render({ force: true });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(
      `Import stopped after ${result.created} documents created and ${result.updated} updated; ` +
        `${result.foldersCreated} folders created and ${result.foldersUpdated} updated. ` +
        `Completed changes remain in the world. ${message}`,
      { cause: error },
    );
  }
  return result;
}
