import { normalizeXpCurveParameters } from "../../functions/xp-curve/calculate";
import type {
  XpCurveConfiguratorInitialization,
  XpCurveConfiguratorSettings,
} from "../../../types/xp-curve/Configuration";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";
import { getCurveRoster } from "./roster";
import { getXpCurveSettings, saveXpCurveSettings } from "./settings/load";

export function getXpCurveConfiguratorInitialization(): XpCurveConfiguratorInitialization {
  const settings = getXpCurveSettings();
  const { actors, rosterIssue } = getCurveRoster();

  return {
    ...settings,
    actors,
    rosterIssue,
  };
}

export async function saveXpCurveConfiguratorSettings(
  configuration: XpCurveConfiguratorSettings,
): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.xpCurveConsole);

  await saveXpCurveSettings({
    defaultReason: configuration.defaultReason,
    parameters: normalizeXpCurveParameters(configuration.parameters),
  });
  ui.notifications.info("Curve XP configuration saved.");
}

export async function confirmCurveReset(): Promise<boolean> {
  return (
    (await foundry.applications.api.DialogV2.confirm({
      window: { title: "Reset Curve XP to defaults?" },
      modal: true,
      rejectClose: false,
      content:
        "<p>Restore 10% catch-up, linear gap weighting, weakening above 1,000 XP at strength 1, and a 500 XP ceiling?</p><p>This changes your setup draft. Finish the steps and save to apply it.</p>",
    })) === true
  );
}

export async function confirmCurveCancel(): Promise<boolean> {
  return (
    (await foundry.applications.api.DialogV2.confirm({
      window: { title: "Discard Curve XP setup?" },
      modal: true,
      rejectClose: false,
      content: "<p>Your curve changes have not been saved. Discard them and close setup?</p>",
    })) === true
  );
}
