import type { ToolkitHomeSection } from "../../../../types/toolkit-home/Console";
import type { ToolkitApplicationHandle } from "../../../../types/module/api/ModuleApi";
import { openFearConsole } from "../../fear-console/view/open";
import { openSessionManagementConsole } from "../../session-management/view/open";
import { openPartyXp, openTargetXp } from "../../../foundry/xp-award/dialog";
import { openConfigureParty } from "../../configure-party/view/ConfigurePartyApplication";
import { openXpCurveConfigurator } from "../../xp-curve-configurator/view/open";
import { openXpCurveConsole } from "../../xp-curve-console/view/open";
import { ToolkitHomeApplication } from "./ToolkitHomeApplication";
import { openAdministrationConsole } from "../../administration-console/view/open";
import { openCombatConsole } from "../../combat-console/view/open";
import { openDamageConsole } from "../../damage-console/view/open";
import { openDarkWhispersConsole } from "../../dark-whispers-console/view/open";
import { openGroupTestConsole } from "../../group-test-console/view/open";
import { openTokenToolsConsole } from "../../token-tools-console/view/open";
import { openSceneManagementConsole } from "../../scene-management-console/view/open";
import { openImperialCalendarCalculator } from "../../imperial-calendar/view/open";

export async function openToolkitHome(): Promise<ToolkitApplicationHandle> {
  const sections: ToolkitHomeSection[] = [
    {
      id: "gameplay",
      label: "Gameplay",
      actions: [
        action(
          "combat",
          "Combat Console",
          "Manage Advantage and condition checks.",
          "fa-solid fa-swords",
          openCombatConsole,
        ),
        action(
          "damage",
          "Damage Console",
          "Apply damage to several actors.",
          "fa-solid fa-bolt",
          openDamageConsole,
        ),
        action(
          "group-test",
          "Secret Group Tests",
          "Run private WFRP4e tests for a group.",
          "fa-solid fa-dice-d100",
          openGroupTestConsole,
        ),
        action(
          "dark-whispers",
          "Dark Whispers",
          "Send temptations to characters with Corruption.",
          "fa-solid fa-comment-dots",
          openDarkWhispersConsole,
        ),
        action(
          "fear",
          "Fear Console",
          "Apply Fear and Terror through WFRP4e.",
          "fa-solid fa-ghost",
          openFearConsole,
        ),
        action(
          "xp-curve",
          "Curve XP",
          "Review and award campaign catch-up XP.",
          "fa-solid fa-chart-line",
          openXpCurveConsole,
        ),
        action(
          "party-xp",
          "Party XP",
          "Award XP to the configured party roster.",
          "fa-solid fa-award",
          openPartyXp,
        ),
        action(
          "target-xp",
          "Target XP",
          "Award XP to targeted characters.",
          "fa-solid fa-bullseye",
          openTargetXp,
        ),
        action(
          "configure-party",
          "Configure Party",
          "Set party membership and XP rates.",
          "fa-solid fa-people-group",
          openConfigureParty,
        ),
        action(
          "token-tools",
          "Token Vision & Light",
          "Apply vision modes and light presets.",
          "fa-solid fa-eye",
          openTokenToolsConsole,
        ),
      ],
    },
    {
      id: "campaign",
      label: "Campaign",
      actions: [
        action(
          "configure-curve-xp",
          "Configure Curve XP",
          "Tune catch-up with guided curves and session forecasts.",
          "fa-solid fa-sliders",
          openXpCurveConfigurator,
        ),
        action(
          "imperial-calendar",
          "Imperial Calendar Calculator",
          "Measure elapsed time between Imperial dates and times.",
          "fa-solid fa-calendar-days",
          openImperialCalendarCalculator,
        ),
        action(
          "scene-management",
          "Scene Management",
          "Open common Scene and token-viewing actions.",
          "fa-solid fa-map",
          openSceneManagementConsole,
        ),
        action(
          "session",
          "Session Management",
          "Record session turnover and history.",
          "fa-solid fa-calendar-check",
          openSessionManagementConsole,
        ),
        action(
          "administration",
          "Administration Console",
          "Manage Scenes, compendium visibility, players, and utility rolls.",
          "fa-solid fa-screwdriver-wrench",
          openAdministrationConsole,
        ),
      ],
    },
  ];
  const application = new ToolkitHomeApplication(sections);
  await application.render(true);
  return application;
}

function action(
  id: string,
  label: string,
  description: string,
  icon: string,
  openApplication: () => Promise<ToolkitApplicationHandle>,
) {
  return {
    description,
    icon,
    id,
    label,
    open: async () => {
      await openApplication();
    },
  };
}
