import type { FoundryActorDocument } from "../../../types/foundry";
import type { PreparedXpAward } from "../../../types/xp-award/XpAward";
import type { XpActorRuntime } from "../xp-curve/actors";
import { createXpActorRuntime } from "../xp-curve/actors";
import { ensurePartyConfiguration } from "../party/configuration";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";
import { isRecord } from "../../functions/records/parse";

export async function prepareXpRecipients(
  mode: PreparedXpAward["mode"],
): Promise<PreparedXpAward["actors"]> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.xpAwards);
  const runtimes: XpActorRuntime[] = [];
  if (mode === "targets") {
    const targets = Array.from(game.user.targets ?? []);
    if (!targets.length) throw new Error("Target at least one character before opening Target XP.");
    for (const token of targets) {
      if (!token.actor || token.actor.type !== "character")
        throw new Error("Every target must be a character actor that can receive XP.");
      const runtime = createXpActorRuntime(token.actor, "standard", true, 100, "Target");
      runtime.choice.id = token.actor.uuid;
      runtimes.push(runtime);
    }
  } else {
    const party = await ensurePartyConfiguration();
    for (const category of party.categories) {
      if (category.xpPercent === 0) continue;
      for (const id of category.actorIds) {
        const actor = game.actors.get(id);
        if (!actor || actor.type !== "character")
          throw new Error(
            `A member of ${category.name} is missing. Open Configure Party to repair the roster.`,
          );
        const runtime = createXpActorRuntime(
          actor,
          category.id === "companions" ? "companion" : "standard",
          true,
          category.xpPercent,
          category.name,
        );
        runtime.choice.id = actor.uuid;
        runtimes.push(runtime);
      }
    }
    if (!runtimes.length)
      throw new Error("Add XP recipients in Configure Party before opening Party XP.");
  }
  return [...new Map(runtimes.map((runtime) => [runtime.choice.id, runtime.choice])).values()];
}

export async function resolvePreparedXpRecipients(
  prepared: PreparedXpAward,
): Promise<XpActorRuntime[]> {
  const seen = new Set<string>();
  const runtimes: XpActorRuntime[] = [];
  for (const expected of prepared.actors) {
    if (seen.has(expected.id)) throw new Error("The XP preview contains a duplicate recipient.");
    seen.add(expected.id);
    const actor = await fromUuid(expected.id);
    if (!isRecord(actor) || actor["documentName"] !== "Actor" || actor["type"] !== "character")
      throw new Error(`${expected.name} is no longer available. No XP was applied.`);
    const percent = expected.xpPercent;
    if (typeof percent !== "number" || !Number.isFinite(percent) || percent < 0)
      throw new Error("The XP preview contains an invalid percentage.");
    const runtime = createXpActorRuntime(
      actor as unknown as FoundryActorDocument,
      expected.category,
      true,
      percent,
      expected.categoryName,
    );
    runtime.choice.id = expected.id;
    if (runtime.choice.totalXp !== expected.totalXp)
      throw new Error(
        `${expected.name}'s XP has changed since this preview. Review any earlier partial award before opening a new one; this submission changed no XP.`,
      );
    runtimes.push(runtime);
  }
  if (!runtimes.length) throw new Error("No XP recipients are available.");
  return runtimes;
}
