import type { FixedXpAward } from "../../../types/xp-award/XpAward";
import type { XpActorChoice } from "../../../types/xp-curve/XpCurve";

/** One WFRP experience log entry, as far as XP recovery needs it. */
export interface XpLogEntry {
  amount: unknown;
  reason: unknown;
  total: unknown;
}

/**
 * Find a grant written after `baselineLength` with this exact reason. Session reasons are unique
 * per session, so such an entry proves an earlier attempt changed this actor's XP.
 */
export function findRecordedXpGrant(
  choice: XpActorChoice,
  log: readonly XpLogEntry[],
  baselineLength: number,
  reason: string,
): FixedXpAward | undefined {
  const matches = log
    .slice(baselineLength)
    .filter((entry) => entry.reason === reason && Number.isFinite(Number(entry.amount)));
  if (matches.length > 1)
    throw new Error(
      `${choice.name} already has ${matches.length} XP log entries for "${reason}". Check their XP log before continuing.`,
    );
  const [entry] = matches;
  if (!entry) return undefined;
  const amount = Math.round(Number(entry.amount));
  const afterXp = Number.isFinite(Number(entry.total))
    ? Math.round(Number(entry.total))
    : choice.totalXp;
  return {
    actorId: choice.id,
    actorName: choice.name,
    afterXp,
    amount,
    beforeXp: afterXp - amount,
    category: choice.category,
  };
}
