<script setup lang="ts">
import type { XpCurveParameters } from "../../../../../types/xp-curve/XpCurve";
import { useStepGraph, type StepGraphProps } from "./useStepGraph";
import GraphCanvas from "./graph/GraphCanvas.vue";
import DiamondHandle from "./graph/DiamondHandle.vue";
import { plotLeft, plotWidth } from "./graphMath";
const props = defineProps<StepGraphProps>();
const emit = defineEmits<{ update: [key: keyof XpCurveParameters, value: number] }>();
const { graph, definition, start, endDrag, updateDrag, keydown } = useStepGraph(
  props,
  (key, value) => emit("update", key, value),
);
</script>

<template>
  <figure class="tw:@container tw:m-0 tw:min-w-0">
    <figcaption
      class="tw:mt-0! tw:mb-1 tw:text-left! tw:text-sm tw:font-semibold tw:text-base-content! tw:not-italic!"
    >
      {{ graph.title }}
    </figcaption>
    <GraphCanvas
      :description="`${graph.xLabel} on the horizontal axis; ${graph.yLabel} on the vertical axis. Numbered markers match the portraits below.`"
      description-id="curve-description"
      title-id="curve-title"
      :title="graph.title"
      :markers="graph.markers"
      :maximum-x-label="`${Math.round(graph.bounds.maximumX)} XP`"
      :minimum-y-label="graph.weakening ? '0%' : '0'"
      :maximum-y-label="graph.weakening ? '100%' : `${Math.round(graph.bounds.maximumY)}`"
      :series="graph.series"
      :vertical-guide-x="graph.handle.x"
      :x-axis-label="graph.xLabel"
      :y-axis-label="graph.yLabel"
      @pointercancel="endDrag"
      @pointermove="updateDrag"
      @pointerup="endDrag"
    >
      <template #guides>
        <line
          v-if="step === 'maximumAward'"
          :x1="plotLeft"
          :x2="plotLeft + plotWidth"
          :y1="graph.handle.y"
          :y2="graph.handle.y"
          stroke="currentColor"
          stroke-dasharray="5 5"
        />
      </template>
      <template #handles>
        <DiamondHandle
          v-if="step !== 'review'"
          :label="definition.label"
          :value-min="definition.min"
          :value-max="definition.max"
          :value-now="parameters[step]"
          :value-text="`${parameters[step]} ${definition.unit}`"
          :x="graph.handle.x"
          :y="graph.handle.y"
          @pointerdown="start"
          @keydown="keydown"
        />
      </template>
    </GraphCanvas>
    <p v-if="step !== 'review'" class="tw:my-1 tw:text-xs">
      Drag the square handle, focus it and use arrow keys, or enter a value below.
    </p>
    <p v-if="step === 'curveExponent' && parameters.catchUpRate === 0" class="tw:text-sm">
      The pace is zero, so this curve has no height to shape. Go Back to increase the pace first.
    </p>
    <p v-if="graph.series.length > 1" class="tw:my-1 tw:text-xs">
      Lines show the configured category rates. Portrait markers include their category’s
      percentage.
    </p>
  </figure>
</template>
