<script setup lang="ts">
import { computed, ref } from "vue";
import type { XpActorChoice, XpAwardPlan } from "../../../../types/xp-curve/XpCurve";
const props = defineProps<{ actors: XpActorChoice[]; plan: XpAwardPlan; numbered?: boolean }>();
const missingImages = ref(new Set<string>());
const portraits = computed(() =>
  props.plan.awards.map((award) => {
    const actor = props.actors.find((entry) => entry.id === award.actorId);
    return {
      ...award,
      img: actor?.img || "icons/svg/mystery-man.svg",
      description: `${award.actorName} · ${actor?.categoryName ?? "Party"} · ${Math.round(award.recipientMultiplier * 100)}% · ${award.beforeXp} → ${award.afterXp} XP`,
    };
  }),
);
</script>

<template>
  <section class="tw:min-w-0" aria-label="Curve XP recipients">
    <p v-if="plan.leader" class="tw:my-2 tw:text-sm">
      <i class="fa-solid fa-crown" aria-hidden="true" />
      <strong>Party leader: {{ plan.leader.name }}</strong> ·
      {{ plan.highestXp.toLocaleString() }} XP
    </p>
    <p v-if="!actors.length" class="tw:text-sm">
      No configured characters to preview.
      {{
        numbered ? "Switch to Example to explore the curve." : "Add characters in Configure Party."
      }}
    </p>
    <ul
      class="tw:m-0 tw:flex tw:[list-style:none] tw:flex-wrap tw:gap-3 tw:p-0!"
      aria-label="Final curve bonuses"
    >
      <li
        v-for="(award, index) in portraits"
        :key="award.actorId"
        class="tw:flex tw:w-20 tw:flex-col tw:items-center tw:gap-1 tw:text-center"
        :title="award.description"
        tabindex="0"
      >
        <img
          v-if="!missingImages.has(award.img)"
          :src="award.img"
          :alt="award.actorName"
          width="44"
          height="44"
          class="tw:size-11 tw:rounded-full tw:object-cover"
          @error="missingImages.add(award.img)"
        />
        <span
          v-else
          class="tw:grid tw:size-11 tw:place-items-center tw:rounded-full tw:bg-base-200 tw:font-semibold"
          role="img"
          :aria-label="award.actorName"
          >{{ award.actorName.slice(0, 2).toUpperCase() }}</span
        >
        <span class="tw:text-sm tw:font-semibold"
          ><span v-if="numbered">{{ index + 1 }}. </span>+{{ award.award }} XP</span
        >
      </li>
    </ul>
    <p v-if="plan.leader && plan.totalAward === 0" class="tw:mt-3 tw:text-sm">
      Nobody currently receives a curve bonus.
    </p>
  </section>
</template>
