import type {
  CampaignContent,
  CampaignImportPlan,
  CampaignSource,
} from "../../../types/campaign-import";

/** Only existing protected actors that will actually be updated need a recovery snapshot. */
export function playerCharacterUpdates(
  plan: CampaignImportPlan,
  existing: CampaignContent,
  protectedActorIds: string[],
): CampaignSource[] {
  const updated = new Set(plan.documents.Actor.update.map((actor) => actor._id));
  const protectedIds = new Set(protectedActorIds);
  return existing.Actor.filter((actor) => protectedIds.has(actor._id) && updated.has(actor._id));
}
