import type { CampaignContent, CampaignImportPlan } from "../../../types/campaign-import";
import type { CampaignImportRequest } from "../../../types/api/CampaignImporter";
import { CAMPAIGN_PACKS, CAMPAIGN_TYPES } from "./content";

const escape = (value: string): string => foundry.utils.escapeHTML(value);

export const campaignImportDialogClass = "wfrp4e-enhanced-fear-terror-campaign-import";

export async function chooseCampaignContent(
  source: CampaignContent,
): Promise<CampaignImportRequest | null> {
  const rows = CAMPAIGN_TYPES.map(
    (type) =>
      `<div class="form-group"><label for="campaign-${type}">${escape(
        CAMPAIGN_PACKS.filter((pack) => pack.type === type)
          .map((pack) => pack.label)
          .join(", "),
      )} (${source[type].length})</label>` +
      `<input type="checkbox" id="campaign-${type}" name="${type}" checked></div>`,
  ).join("");
  const selection = await foundry.applications.api.DialogV2.wait<CampaignImportRequest | false>({
    classes: [campaignImportDialogClass],
    window: { title: "Import Campaign Content" },
    position: { width: 420 },
    content:
      `<p>Choose campaign content to add to this world.</p>${rows}` +
      `<div class="form-group"><label for="campaign-mode">Existing content</label>` +
      `<select id="campaign-mode" name="mode"><option value="skip">Keep existing content</option>` +
      `<option value="update">Update from the compendiums</option></select></div>` +
      `<p>Updates replace selected content, including its items, pages and scene elements. Matching entries retain their current access permissions.</p>`,
    buttons: [
      { action: "cancel", label: "Cancel", callback: () => false },
      {
        action: "review",
        label: "Review Import",
        default: true,
        callback: (_event, button) => {
          const form = button.form;
          if (!form) throw new Error("Import form is unavailable.");
          const values = new FormData(form);
          const selectedTypes = CAMPAIGN_TYPES.filter((type) => values.has(type));
          return { selectedTypes, mode: values.get("mode") === "update" ? "update" : "skip" };
        },
      },
    ],
  });
  return selection || null;
}

export async function chooseOwnership(
  request: CampaignImportRequest,
  pendingIds: string[],
): Promise<CampaignImportRequest | null> {
  const users = game?.users.contents ?? [];
  const unknownIds = pendingIds.filter(
    (id) => !users.some((user) => user.id === id) && request.ownershipMap?.[id] === undefined,
  );
  if (!unknownIds.length) return request;
  const destinations = users
    .map((user) => `<option value="${escape(user.id)}">${escape(user.name)}</option>`)
    .join("");
  const rows = unknownIds
    .map(
      (id) =>
        `<div class="form-group"><label for="owner-${escape(id)}">` +
        `Saved user ${escape(id)}</label><select id="owner-${escape(id)}" name="${escape(id)}">` +
        `<option value="">Do not grant this user's access</option>${destinations}</select></div>`,
    )
    .join("");
  const ownershipMap = await foundry.applications.api.DialogV2.wait<
    Record<string, string | null> | false
  >({
    classes: [campaignImportDialogClass],
    window: { title: "Match Saved Access" },
    position: { width: 440 },
    content:
      `<p>Some saved permissions refer to users absent from this world. Choose a destination user ` +
      `only when you know who the saved user is. Unassigned grants are omitted; default visibility is retained. ` +
      `Existing documents keep their current permissions.</p>${rows}`,
    buttons: [
      { action: "cancel", label: "Cancel", callback: () => false },
      {
        action: "continue",
        label: "Continue",
        default: true,
        callback: (_event, button) => {
          if (!button.form) throw new Error("Access form is unavailable.");
          const values = new FormData(button.form);
          return Object.fromEntries(
            unknownIds.map((id) => [id, String(values.get(id) ?? "") || null]),
          );
        },
      },
    ],
  });
  return ownershipMap
    ? { ...request, ownershipMap: { ...request.ownershipMap, ...ownershipMap } }
    : null;
}

export function confirmCampaignImport(plan: CampaignImportPlan): Promise<boolean | null> {
  const rows = CAMPAIGN_TYPES.map((type) => {
    const label = CAMPAIGN_PACKS.filter((pack) => pack.type === type)
      .map((pack) => pack.label)
      .join(", ");
    const batch = plan.documents[type];
    return `<tr><th scope="row">${escape(label)}</th><td>${batch.create.length}</td><td>${batch.update.length}</td><td>${batch.skipped}</td></tr>`;
  }).join("");
  return foundry.applications.api.DialogV2.confirm({
    classes: [campaignImportDialogClass],
    window: { title: "Confirm Campaign Content Import" },
    content:
      `<table><thead><tr><th>Content</th><th>Add</th><th>Update</th><th>Keep</th></tr></thead><tbody>${rows}</tbody></table>` +
      `<p>Folders: ${plan.folders.create.length} added, ${plan.folders.update.length} updated.</p>` +
      (plan.counts.update
        ? `<p><strong>Updates replace existing content with the packaged version.</strong> Current access permissions are retained.</p>`
        : "") +
      `<p>No top-level world documents are deleted. Campaign settings and user character assignments are unchanged.</p>`,
  });
}
