import type {
  CampaignImportRequest,
  CampaignImportResult,
} from "../../../types/api/CampaignImporter";
import type { CampaignImportPlan } from "../../../types/campaign-import";
import { planCampaignImport } from "../../functions/importer";
import { playerCharacterUpdates } from "../../functions/importer/player-characters";
import { PACKAGE_ID, PACKAGE_TITLE } from "../../constants";
import {
  CAMPAIGN_PACKS,
  loadCampaignContent,
  requireCampaignGM,
  selectedWorldSignature,
  snapshotCampaignWorld,
} from "./content";
import { chooseCampaignContent, chooseOwnership, confirmCampaignImport } from "./dialogs";
import { executeCampaignImport } from "./execute";
import { backupPlayerCharacters, confirmPlayerCharacterUpdates } from "./player-characters";
import { protectedPlayerCharacterIds } from "./system";
import { queueFolderTidy } from "../folders/queue";

let importing = false;

/** Shared UI entry point for the sidebar and module settings. */
export async function openCampaignImport(): Promise<void> {
  try {
    await importCampaign();
  } catch (error) {
    console.error(`${PACKAGE_TITLE}: Campaign import failed.`, error);
    ui.notifications.error(error instanceof Error ? error.message : String(error), {
      permanent: true,
    });
  }
}

export async function previewCampaignImport(
  request: CampaignImportRequest,
): Promise<CampaignImportPlan> {
  const source = await loadCampaignContent();
  return planCampaignImport({
    packageId: PACKAGE_ID,
    packs: CAMPAIGN_PACKS,
    ...request,
    source,
    existing: snapshotCampaignWorld(source),
    destinationUserIds: game?.users.contents.map((user) => user.id) ?? [],
  });
}

/** Native dialogs and the module API share the same planned import workflow. */
export async function importCampaign(
  request?: CampaignImportRequest,
): Promise<CampaignImportResult | null> {
  const currentGame = requireCampaignGM();
  if (importing) throw new Error("A campaign import is already open in this browser.");
  importing = true;
  try {
    const source = await loadCampaignContent();
    const selection = request ?? (await chooseCampaignContent(source));
    if (!selection) return null;
    const existing = snapshotCampaignWorld(source);
    const destinationUserIds = game?.users.contents.map((user) => user.id) ?? [];
    const draft = planCampaignImport({
      packageId: PACKAGE_ID,
      packs: CAMPAIGN_PACKS,
      ...selection,
      source,
      existing,
      destinationUserIds,
    });
    const assigned = await chooseOwnership(selection, draft.droppedOwnershipIds);
    if (!assigned) return null;
    const plan = planCampaignImport({
      packageId: PACKAGE_ID,
      packs: CAMPAIGN_PACKS,
      ...assigned,
      source,
      existing,
      destinationUserIds,
    });
    if (
      !plan.counts.create &&
      !plan.counts.update &&
      !plan.folders.create.length &&
      !plan.folders.update.length
    ) {
      ui.notifications.info(
        `${PACKAGE_TITLE}: All selected content is already present; nothing changed.`,
      );
      return {
        created: 0,
        updated: 0,
        skipped: plan.counts.skipped,
        foldersCreated: 0,
        foldersUpdated: 0,
      };
    }
    if (!(await confirmCampaignImport(plan))) return null;
    const playerCharacters = playerCharacterUpdates(
      plan,
      existing,
      protectedPlayerCharacterIds(existing.Actor),
    );
    if (!(await confirmPlayerCharacterUpdates(playerCharacters))) return null;
    const selectedTypes = assigned.selectedTypes;
    const before = selectedWorldSignature(source, existing, selectedTypes);
    function requireUnchangedWorld(): void {
      const after = selectedWorldSignature(source, snapshotCampaignWorld(source), selectedTypes);
      if (before !== after)
        throw new Error(
          "Campaign content changed while the import was open. Review a new import before continuing.",
        );
    }
    requireUnchangedWorld();
    await backupPlayerCharacters(playerCharacters);
    const result = await queueFolderTidy(currentGame, async () => {
      requireUnchangedWorld();
      return executeCampaignImport(plan, playerCharacters);
    });
    ui.notifications.info(
      `${PACKAGE_TITLE}: ${result.created} added, ${result.updated} updated, ${result.skipped} kept.`,
    );
    return result;
  } finally {
    importing = false;
  }
}
