import {
  registerAdministrationHooks,
  warnAboutUnassignedPlayers,
} from "../foundry/administration/hooks";
import { registerAdministrationSettings } from "../foundry/administration/settings/register";
import { registerCombatHooks } from "../foundry/combat/hooks";
import { registerCombatSettings } from "../foundry/combat/settings/register";
import { MODULE_ID, WFRP4E_SYSTEM_ID } from "../constants";
import { registerActorSheetEntry } from "../foundry/fear-terror/actor-sheet/register";
import { registerDarkWhispersSettings } from "../foundry/dark-whispers/settings/register";
import { registerDarkWhispersChatHooks } from "../foundry/dark-whispers/service";
import { registerGroupTestHooks } from "../foundry/group-test/service";
import { registerGroupTestSettings } from "../foundry/group-test/settings/register";
import { registerSceneControl } from "../foundry/fear-terror/scene-controls/register";
import { registerFearTerrorSettings } from "../foundry/fear-terror/settings/register";
import { registerSessionManagementSettings } from "../foundry/session-management/settings/register";
import { registerSessionManagementHooks } from "../foundry/session-management/hooks";
import { registerToolkitHomeSettings } from "../foundry/toolkit-home/settings/register";
import { registerTokenToolsSettings } from "../foundry/token-tools/settings/register";
import { registerXpCurveSceneControl } from "../foundry/xp-curve/scene-controls/register";
import { registerXpCurveSettings } from "../foundry/xp-curve/settings/register";
import { registerXpAwardSettings } from "../foundry/xp-award/settings/register";
import { promptToolkitMacroImport, registerMacroImportSetting } from "../foundry/macros/sync";
import { registerPartySettings } from "../foundry/party/settings";

export function registerToolkitHooks(): void {
  registerAdministrationHooks();
  registerCombatHooks();
  registerDarkWhispersChatHooks();
  registerGroupTestHooks();
  registerSessionManagementHooks();
  Hooks.once("setup", registerMacroImportSetting);
  Hooks.once("init", () => {
    console.info(`${MODULE_ID} | Initializing`);
    registerAdministrationSettings();
    registerCombatSettings();
    registerFearTerrorSettings();
    registerDarkWhispersSettings();
    registerGroupTestSettings();
    registerSessionManagementSettings();
    registerToolkitHomeSettings();
    registerTokenToolsSettings();
    registerXpAwardSettings();
    registerPartySettings();
    registerXpCurveSettings();
    registerActorSheetEntry();
    registerSceneControl();
    registerXpCurveSceneControl();
  });

  Hooks.once("ready", () => {
    if (game.system.id !== WFRP4E_SYSTEM_ID) {
      console.warn(
        `${MODULE_ID} | Loaded outside ${WFRP4E_SYSTEM_ID}; skipping module API registration.`,
      );
      return;
    }

    warnAboutUnassignedPlayers();
    void promptToolkitMacroImport().catch((error: unknown) => {
      console.error(`${MODULE_ID} | Toolkit macro import failed.`, error);
      ui.notifications.error("Toolkit macro import failed. See the browser console for details.");
    });
    console.info(`${MODULE_ID} | Ready`);
  });
}
