<script setup lang="ts">
import { storeToRefs } from "pinia";
import type { PartyConfiguration, PartyZoneActions } from "../../../../../types/party/Party";
import { usePartyZonesStore } from "../../state/zones";
const props = defineProps<{
  initialConfiguration: PartyConfiguration;
  actions: PartyZoneActions;
}>();
const store = usePartyZonesStore();
store.initialize(props.initialConfiguration, props.actions);
props.actions.bindCloseGuard(store.canClose);
const { configuration, error, busy } = storeToRefs(store);
</script>
<template>
  <main class="tw:flex tw:h-full tw:min-h-0 tw:flex-col tw:gap-4 tw:p-3">
    <p class="tw:m-0 tw:text-sm tw:opacity-70">Set the zones and their shares of Party XP.</p>
    <p v-if="error" role="alert" class="tw:text-error tw:text-sm">{{ error }}</p>
    <form
      id="party-zones-form"
      class="tw:min-h-0 tw:flex-1 tw:overflow-auto"
      @submit.prevent="store.apply"
    >
      <fieldset :disabled="busy" class="tw:m-0 tw:grid tw:gap-3 tw:border-0 tw:p-0">
        <div
          v-for="category in configuration.categories"
          :key="category.id"
          class="tw:flex tw:items-center tw:gap-2"
        >
          <strong
            v-if="['party', 'companions'].includes(category.id)"
            class="tw:min-w-0 tw:flex-1 tw:text-sm"
            >{{ category.name }}</strong
          >
          <input
            v-else
            v-model="category.name"
            aria-label="Zone name"
            required
            class="tw:dui-input tw:dui-input-sm tw:min-w-0 tw:flex-1"
          />
          <label class="tw:flex tw:items-center tw:gap-1 tw:text-sm">
            <input
              v-model.number="category.xpPercent"
              :aria-label="`${category.name} XP percentage`"
              type="number"
              min="0"
              step="any"
              required
              class="tw:dui-input tw:dui-input-sm tw:w-20"
            />
            <span>% XP</span>
          </label>
          <button
            v-if="!['party', 'companions'].includes(category.id)"
            type="button"
            :aria-label="`Remove ${category.name} zone`"
            class="tw:dui-btn tw:dui-btn-ghost tw:dui-btn-sm tw:dui-btn-square"
            @click="store.remove(category.id)"
          >
            <i class="fa-solid fa-trash" aria-hidden="true" />
          </button>
          <span v-else class="tw:w-8" />
        </div>
        <button
          type="button"
          class="tw:dui-btn tw:dui-btn-sm tw:justify-self-start"
          @click="store.add"
        >
          <i class="fa-solid fa-plus" aria-hidden="true" /> Add zone
        </button>
      </fieldset>
    </form>
    <footer class="tw:flex tw:flex-wrap tw:gap-2 tw:border-t tw:border-base-content/15 tw:pt-3">
      <button
        type="button"
        :disabled="busy"
        class="tw:dui-btn tw:dui-btn-ghost tw:dui-btn-sm"
        @click="store.reset"
      >
        Reset party…
      </button>
      <span class="tw:flex-1" />
      <button type="button" :disabled="busy" class="tw:dui-btn tw:dui-btn-sm" @click="store.cancel">
        Cancel
      </button>
      <button
        type="submit"
        form="party-zones-form"
        :disabled="busy"
        class="tw:dui-btn tw:dui-btn-primary tw:dui-btn-sm"
      >
        Apply zones
      </button>
    </footer>
  </main>
</template>
