import type { PackageApi } from "../../../types/api/PackageApi";
import { createModuleApi } from "./create-module-api";
import { importCampaign, previewCampaignImport } from "../importer";
import { importCampaignSettings } from "../settings/import";
import { captureCampaignSettings, exportCampaignSettings } from "../settings/export";

import { campaignSettingsApi } from "../settings/provider";

export function createPackageApi(): PackageApi {
  return {
    ...createModuleApi(),
    ...(import.meta.env.CAMPAIGN_WORLD_MODULE
      ? {
          settingsPresets: campaignSettingsApi,
          importCampaign,
          previewCampaignImport,
          importCampaignSettings,
          exportCampaignSettings,
          captureCampaignSettings,
        }
      : {}),
    openPreviewNotice() {
      console.log("Drowsy’s WFRP4e Toolkit API is available.");
    },
  };
}
