import type { SettingsPresetApi, PresetDefinition } from "../../../types/settings-presets/Protocol";
import { PACKAGE_ID } from "../../constants";
import { CAMPAIGN_SETTINGS, CAMPAIGN_PRESET_METADATA } from "./sources";
import {
  isSettingsNamespaceActive,
  inspectPreferences,
  applyPreferences,
} from "./preset-runtime/engine";
import { resolvePreferences } from "./preset-runtime/coordination";
import { captureSettings } from "./preset-runtime/export";
export function campaignPresets(): PresetDefinition[] {
  return Object.entries(CAMPAIGN_SETTINGS).map(([namespace, values]) => ({
    namespace,
    title: CAMPAIGN_PRESET_METADATA[namespace]?.title ?? namespace,
    ...CAMPAIGN_PRESET_METADATA[namespace],
    entries: Object.entries(values).map(([key, value]) => ({ namespace, key, value })),
  }));
}
export function campaignEntries(namespace?: string) {
  if (namespace !== undefined && !Object.hasOwn(CAMPAIGN_SETTINGS, namespace))
    throw new Error(`No campaign settings source exists for ${namespace}.`);
  return campaignPresets()
    .filter((preset) => namespace === undefined || namespace === preset.namespace)
    .flatMap((preset) => preset.entries);
}
export const campaignSettingsApi: SettingsPresetApi = {
  version: 1,
  getPresets: () =>
    campaignPresets().filter((preset) => isSettingsNamespaceActive(preset.namespace)),
  inspect: (namespace) => inspectPreferences(PACKAGE_ID, campaignEntries(namespace)),
  apply: async (namespace) => applyPreferences(PACKAGE_ID, campaignEntries(namespace)),
  resolve: async (namespace) => resolvePreferences(PACKAGE_ID, campaignEntries(namespace)),
  capture: captureSettings,
};
