<script setup lang="ts">
import { storeToRefs } from "pinia";
import { useXpCurveConsoleStore } from "../state/store";
import type {
  XpCurveConsoleActions,
  XpCurveConsoleInitialization,
} from "../../../../types/xp-curve/Console";
import CurveAwardPreview from "../../shared/view/CurveAwardPreview.vue";
const props = defineProps<{
  actions: XpCurveConsoleActions;
  initialization: XpCurveConsoleInitialization;
}>();
const store = useXpCurveConsoleStore();
store.initialize(props.initialization, props.actions);
const {
  actors,
  reason,
  rosterIssue,
  errorMessage,
  isWorking,
  complete,
  plan,
  canApply,
  resolvedReason,
} = storeToRefs(store);
</script>

<template>
  <form
    class="tw:flex tw:h-full tw:min-h-0 tw:min-w-0 tw:flex-col tw:bg-base-100! tw:text-base-content!"
    @submit.prevent="store.applyAwards"
  >
    <div class="tw:min-h-0 tw:min-w-0 tw:flex-1 tw:overflow-auto tw:p-4">
      <p class="tw:mt-0 tw:text-sm">
        Catch-up bonuses for your configured party. Category XP percentages apply.
      </p>
      <p v-if="errorMessage" class="tw:dui-alert tw:dui-alert-error" role="alert">
        {{ errorMessage }}
      </p>
      <p v-if="complete" role="status">Curve XP awarded.</p>
      <p v-if="rosterIssue" role="status">
        {{ rosterIssue }}
        <button class="tw:dui-btn tw:dui-btn-sm" type="button" @click="actions.openParty">
          Configure Party
        </button>
        Save your party, then reopen Curve XP to refresh this preview.
      </p>
      <CurveAwardPreview :actors="actors" :plan="plan" />
      <label for="curve-award-reason" class="tw:mt-5 tw:mb-1 tw:block tw:text-sm tw:font-semibold"
        >XP log reason</label
      >
      <input
        id="curve-award-reason"
        v-model="reason"
        class="tw:dui-input tw:dui-input-sm tw:w-full tw:min-w-0"
        type="text"
        :disabled="isWorking || complete"
      />
      <p class="tw:mb-0 tw:break-words tw:text-sm">
        <strong>Log preview:</strong> {{ resolvedReason || "No reason" }}
      </p>
    </div>
    <footer
      class="tw:flex tw:shrink-0 tw:flex-wrap tw:justify-end tw:gap-2 tw:border-t tw:border-base-content/20 tw:p-3"
    >
      <button
        class="tw:dui-btn tw:dui-btn-sm"
        type="button"
        :disabled="isWorking"
        @click="actions.close"
      >
        Cancel
      </button>
      <button
        class="tw:dui-btn tw:dui-btn-sm tw:dui-btn-primary"
        type="submit"
        :disabled="!canApply"
      >
        {{ isWorking ? "Awarding…" : `Award ${plan.totalAward} total XP` }}
      </button>
    </footer>
  </form>
</template>
