import { ConfigurePartyApplication } from "../../apps/configure-party/view/ConfigurePartyApplication";
import { MODULE_ID } from "../../constants";
import { PARTY_SETTING } from "./configuration";

export function registerPartySettings(): void {
  game.settings.register(MODULE_ID, PARTY_SETTING, {
    name: "Party configuration",
    hint: "The shared party roster and category XP percentages.",
    config: false,
    scope: "world",
    type: String,
    default: "",
  });
  game.settings.registerMenu(MODULE_ID, "configureParty", {
    name: "Configure Party",
    label: "Configure Party",
    icon: "fa-solid fa-people-group",
    hint: "Organize Party, Companions, and other XP recipients.",
    restricted: true,
    type: ConfigurePartyApplication,
  });
}
