<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref } from "vue";
import { storeToRefs } from "pinia";
import type { PartyActions, PartyInitialization } from "../../../../types/party/Party";
import { escapeHtml } from "../../../functions/xp-curve/reason";
import { useConfigurePartyStore } from "../state/store";

const props = defineProps<{ initialization: PartyInitialization; actions: PartyActions }>();
const store = useConfigurePartyStore();
store.initialize(props.initialization, props.actions);
props.actions.bindCloseGuard(store.canClose);
const { configuration, actors, error, busy } = storeToRefs(store);
const root = ref<HTMLElement>();
const overZone = ref("");
const actorMap = computed(() => new Map(actors.value.map((actor) => [actor.id, actor])));
const actorName = (id: string): string => actorMap.value.get(id)?.name || `Missing actor (${id})`;
let disposeMenu: (() => void) | undefined;
onMounted(() => {
  disposeMenu = props.actions.bindMenu(root.value!, {
    categories: () => configuration.value.categories,
    busy: () => busy.value,
    move: store.moveActor,
    remove: store.removeActor,
  });
});
onBeforeUnmount(() => disposeMenu?.());
function dragActor(event: DragEvent, actorId: string): void {
  if (!event.dataTransfer || busy.value) return;
  event.dataTransfer.effectAllowed = "move";
  event.dataTransfer.setData(
    "text/plain",
    JSON.stringify({ type: "Actor", uuid: `Actor.${actorId}` }),
  );
}
function dropActor(event: DragEvent, categoryId: string): void {
  overZone.value = "";
  const data = event.dataTransfer?.getData("text/plain");
  if (data && !busy.value) void store.drop(data, categoryId);
}
function openMenu(event: Event): void {
  const target = event.currentTarget;
  if (!(target instanceof HTMLElement)) return;
  const { left, bottom } = target.getBoundingClientRect();
  target.dispatchEvent(
    new MouseEvent("contextmenu", {
      bubbles: true,
      cancelable: true,
      clientX: left,
      clientY: bottom,
    }),
  );
}
function menuKey(event: KeyboardEvent): void {
  if (event.key !== "ContextMenu" && !(event.shiftKey && event.key === "F10")) return;
  event.preventDefault();
  openMenu(event);
}
</script>

<template>
  <main ref="root" class="party-gallery tw:flex tw:h-full tw:min-h-0 tw:flex-col tw:gap-3 tw:p-3">
    <header class="tw:flex tw:items-center tw:justify-between tw:gap-3">
      <p class="tw:m-0 tw:text-xs tw:opacity-60">
        Drag actors between zones. Right-click for actions.
      </p>
      <button
        type="button"
        :disabled="busy"
        aria-label="Configure party zones"
        title="Configure party zones"
        class="tw:dui-btn tw:dui-btn-ghost tw:dui-btn-sm tw:dui-btn-square"
        @click="store.configure"
      >
        <i class="fa-solid fa-gear" aria-hidden="true" />
      </button>
    </header>
    <p v-if="error" class="tw:m-0 tw:text-error tw:text-sm" role="alert">{{ error }}</p>
    <div class="party-zones tw:min-h-0 tw:flex-1 tw:overflow-auto">
      <section
        v-for="category in configuration.categories"
        :key="category.id"
        :data-party-category="category.id"
        :aria-label="category.name"
        class="party-zone"
        :class="{ 'party-zone-over': overZone === category.id }"
        @dragover.prevent="overZone = category.id"
        @dragleave.self="overZone = ''"
        @drop.prevent="dropActor($event, category.id)"
      >
        <header class="tw:mb-3 tw:flex tw:items-center tw:justify-between tw:gap-2">
          <h2 class="tw:m-0 tw:font-sans tw:text-sm tw:font-semibold">{{ category.name }}</h2>
          <span class="tw:text-xs tw:opacity-60">{{ category.xpPercent }}% XP</span>
        </header>
        <div class="party-portraits">
          <button
            v-for="id in category.actorIds"
            :key="id"
            type="button"
            :disabled="busy"
            :draggable="!busy"
            :data-party-actor="id"
            :data-tooltip="escapeHtml(actorName(id))"
            :aria-label="actorName(id)"
            aria-haspopup="menu"
            class="party-portrait"
            :class="{ 'party-portrait-missing': !actorMap.has(id) }"
            @dragstart="dragActor($event, id)"
            @dragend="overZone = ''"
            @click.stop="openMenu"
            @keydown="menuKey"
          >
            <img
              :src="actorMap.get(id)?.img || 'icons/svg/mystery-man.svg'"
              alt=""
              draggable="false"
            />
            <i
              v-if="!actorMap.has(id)"
              class="fa-solid fa-triangle-exclamation party-missing-marker"
              aria-hidden="true"
            />
          </button>
          <button
            type="button"
            :disabled="busy"
            class="party-portrait party-add"
            :aria-label="`Add actor to ${category.name}`"
            :title="`Add actor to ${category.name}`"
            @click="store.addActor(category.id)"
          >
            <i class="fa-solid fa-plus" aria-hidden="true" />
          </button>
          <span v-if="!category.actorIds.length" class="party-empty tw:text-xs tw:opacity-50"
            >Drop actors here</span
          >
        </div>
      </section>
    </div>
    <footer class="tw:flex tw:justify-end tw:gap-2 tw:border-t tw:border-base-content/15 tw:pt-3">
      <button type="button" :disabled="busy" class="tw:dui-btn tw:dui-btn-sm" @click="store.cancel">
        Cancel
      </button>
      <button
        type="button"
        :disabled="busy"
        class="tw:dui-btn tw:dui-btn-primary tw:dui-btn-sm"
        @click="store.save"
      >
        Save party
      </button>
    </footer>
  </main>
</template>

