import type { ToolkitMacroSource } from "../../../types/macros/Sync";
import { isRecord, readString } from "../../functions/records/parse";
import { MODULE_ID } from "../../constants";

export const TOOLKIT_MACRO_PACK = `${MODULE_ID}.macros`;

export function extractToolkitMacro(value: unknown): ToolkitMacroSource | null {
  if (!isRecord(value)) return null;
  const id = readString(value["_id"]);
  if (!id) return null;
  const stats = isRecord(value["_stats"]) ? value["_stats"] : {};
  const flags = isRecord(value["flags"]) ? value["flags"] : {};
  const core = isRecord(flags["core"]) ? flags["core"] : {};
  const moduleFlags = isRecord(flags[MODULE_ID]) ? flags[MODULE_ID] : {};
  const provenance = readString(stats["compendiumSource"]) || readString(core["sourceId"]);
  const prefix = `Compendium.${TOOLKIT_MACRO_PACK}.`;
  const sourceId = provenance.startsWith(prefix) ? provenance.slice(prefix.length) : "";
  return {
    id,
    name: readString(value["name"]),
    command: readString(value["command"]),
    img: readString(value["img"]),
    scope: readString(value["scope"]),
    type: readString(value["type"]),
    folderId: readString(value["folder"]),
    ...(sourceId && !sourceId.includes(".")
      ? { sourceId }
      : sourceId.startsWith("Macro.") && !sourceId.slice(6).includes(".")
        ? { sourceId: sourceId.slice(6) }
        : {}),
    ...(typeof moduleFlags["macroFolder"] === "string"
      ? { importedFolderId: moduleFlags["macroFolder"] }
      : {}),
  };
}
