import { MODULE_ID } from "../../constants";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";
import {
  createPartyConfiguration,
  parsePartyConfiguration,
  validatePartyConfiguration,
} from "../../functions/party/configuration";
import type {
  PartyActor,
  PartyConfiguration,
  PartyInitialization,
} from "../../../types/party/Party";
import { isRecord } from "../../functions/records/parse";

export const PARTY_SETTING = "partyConfiguration";

export function getPartyActorChoices(): PartyActor[] {
  return Array.from(game.actors)
    .filter((actor) => actor.type === "character")
    .map((actor) => ({
      id: actor.id,
      name: actor.name,
      img: actor.img || "icons/svg/mystery-man.svg",
    }))
    .sort((left, right) => left.name.localeCompare(right.name));
}

function assignedParty(): PartyConfiguration {
  const assigned = Array.from(game.users)
    .filter(
      (user) =>
        !user.isGM && user.character && game.actors.get(user.character.id)?.type === "character",
    )
    .flatMap((user) =>
      user.character && game.actors.get(user.character.id) ? [user.character.id] : [],
    );
  return createPartyConfiguration(assigned);
}

export function getPartyConfiguration(): PartyConfiguration {
  return parsePartyConfiguration(game.settings.get(MODULE_ID, PARTY_SETTING)) ?? assignedParty();
}

export async function ensurePartyConfiguration(): Promise<PartyConfiguration> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.configureParty);
  const existing = parsePartyConfiguration(game.settings.get(MODULE_ID, PARTY_SETTING));
  if (existing) return existing;
  const configuration = assignedParty();
  await savePartyConfiguration(configuration);
  return configuration;
}

export async function savePartyConfiguration(value: PartyConfiguration): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.configureParty);
  const configuration = validatePartyConfiguration(value);
  // Retain missing references for visible repair; never silently drop saved members.
  await game.settings.set(MODULE_ID, PARTY_SETTING, JSON.stringify(configuration));
}

export async function getPartyInitialization(): Promise<PartyInitialization> {
  return { configuration: await ensurePartyConfiguration(), actors: getPartyActorChoices() };
}

export async function resolvePartyDrop(data: string): Promise<PartyActor> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.configureParty);
  let drop: unknown;
  try {
    drop = JSON.parse(data);
  } catch {
    throw new Error("Drag an actor from the Actors sidebar.");
  }
  if (!isRecord(drop) || drop["type"] !== "Actor" || typeof drop["uuid"] !== "string")
    throw new Error("Drag an actor from the Actors sidebar.");
  const actor = await fromUuid(drop["uuid"]);
  if (
    !isRecord(actor) ||
    actor["documentName"] !== "Actor" ||
    actor["type"] !== "character" ||
    typeof actor["id"] !== "string" ||
    !game.actors.get(actor["id"]) ||
    drop["uuid"] !== `Actor.${actor["id"]}`
  )
    throw new Error(
      "Choose a world character actor from the Actors sidebar. NPC characters are welcome.",
    );
  return {
    id: actor["id"],
    name: String(actor["name"]),
    img: String(actor["img"] || "icons/svg/mystery-man.svg"),
  };
}

export async function resetPartyConfiguration(): Promise<PartyConfiguration | null> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.configureParty);
  const confirmed = await foundry.applications.api.DialogV2.confirm({
    modal: true,
    window: { title: "Reset Party?" },
    content:
      "<p>Replace the saved roster with the characters currently assigned to players?</p><p>Party returns to 100% XP and Companions to 50%. Companion membership and custom categories are cleared. Apply the zones, then Save party to keep the reset.</p>",
    rejectClose: false,
  });
  if (!confirmed) return null;
  const configuration = assignedParty();
  return configuration;
}
