import type {
  CampaignContent,
  CampaignDocumentType,
  CampaignPackDefinition,
} from "../../../types/campaign-import";

export const campaignDocumentTypes: CampaignDocumentType[] = [
  "Actor",
  "Item",
  "JournalEntry",
  "Macro",
  "RollTable",
  "Scene",
];

export function emptyCampaignContent(): CampaignContent {
  return { Actor: [], Item: [], JournalEntry: [], Scene: [], Macro: [], RollTable: [], Folder: [] };
}

/** Configuration is authored alongside the campaign's sources, never inferred from other modules. */
export function campaignPacks(value: unknown): CampaignPackDefinition[] {
  if (!Array.isArray(value)) throw new Error("Campaign packs must be an array.");
  const ids = new Set<string>();
  return value.map((entry: unknown) => {
    if (!entry || typeof entry !== "object") throw new Error("Invalid campaign pack definition.");
    const { type, id, label } = entry as Record<string, unknown>;
    if (
      !campaignDocumentTypes.includes(type as CampaignDocumentType) ||
      typeof id !== "string" ||
      !/^[a-z0-9][a-z0-9_-]*$/.test(id) ||
      typeof label !== "string" ||
      !label.trim()
    )
      throw new Error("Campaign packs require a supported type, pack ID and label.");
    if (ids.has(id)) throw new Error(`Duplicate campaign pack ID: ${id}`);
    ids.add(id);
    return { type: type as CampaignDocumentType, id, label };
  });
}
