import type { FoundryActorDocument } from "../../../types/foundry";
import type { XpLogEntry } from "../../functions/xp-award/recovery";
import { getPartyConfiguration } from "../party/configuration";
import type {
  XpActorCategory,
  XpActorChoice,
  XpDefaultSelection,
} from "../../../types/xp-curve/XpCurve";

export interface XpActorRuntime {
  awardExperience: (amount: number, reason: string) => Promise<void>;
  choice: XpActorChoice;
  /** Snapshot of the actor's WFRP experience log when this runtime was read. */
  xpLog: readonly XpLogEntry[];
}

interface WfrpActorXp {
  awardExperience: (amount: number, reason: string) => Promise<void>;
  log: readonly XpLogEntry[];
  totalXp: number;
}

export function getXpActorChoices(defaultSelection: XpDefaultSelection): {
  actors: XpActorChoice[];
  selectionSource: "default" | "targets";
} {
  const configuration = getPartyConfiguration();
  const targetedActorIds = getTargetedActorIds();
  const selectionSource = targetedActorIds === undefined ? "default" : "targets";
  const actors = Array.from(game.actors)
    .filter((actor) => actor.type === "character")
    .map((actor) => {
      const category = configuration.categories.find((entry) => entry.actorIds.includes(actor.id));
      const selected =
        targetedActorIds?.has(actor.id) ??
        (defaultSelection === "world" ||
          (defaultSelection === "party" ? category?.id === "party" : !!category));
      return createXpActorRuntime(
        actor,
        category?.id === "companions" ? "companion" : "standard",
        selected,
        category?.xpPercent ?? 100,
        category?.name ?? "Other",
      ).choice;
    })
    .sort(
      (left, right) =>
        Number(right.selected) - Number(left.selected) || left.name.localeCompare(right.name),
    );
  return { actors, selectionSource };
}

export function getXpActorRuntimes(actorIds: string[]): XpActorRuntime[] {
  const configuration = getPartyConfiguration();

  return actorIds.map((actorId) => {
    const actor = game.actors.get(actorId);

    if (!actor || actor.type !== "character") {
      throw new Error(`XP recipient ${actorId} is no longer an available character actor.`);
    }

    const category = configuration.categories.find((entry) => entry.actorIds.includes(actor.id));
    return createXpActorRuntime(
      actor,
      category?.id === "companions" ? "companion" : "standard",
      true,
      category?.xpPercent ?? 100,
      category?.name ?? "Other",
    );
  });
}

export function createXpActorRuntime(
  actor: FoundryActorDocument,
  category: XpActorCategory,
  selected: boolean,
  xpPercent = 100,
  categoryName = "Target",
): XpActorRuntime {
  const actorXp = extractWfrpActorXp(actor);

  return {
    awardExperience: actorXp.awardExperience,
    choice: {
      category,
      xpPercent,
      categoryName,
      img: actor.img || "icons/svg/mystery-man.svg",
      id: actor.id,
      name: actor.name,
      selected,
      totalXp: actorXp.totalXp,
    },
    xpLog: actorXp.log,
  };
}

function extractWfrpActorXp(actor: FoundryActorDocument): WfrpActorXp {
  const system = actor.system;

  if (!isRecord(system)) {
    throw new Error(`WFRP4e actor "${actor.name}" does not expose readable system data.`);
  }

  const details = system["details"];
  if (!isRecord(details)) {
    throw new Error(`WFRP4e actor "${actor.name}" does not expose XP data.`);
  }

  const experience = details["experience"];
  const savedLog = isRecord(experience) ? experience["log"] : undefined;

  if (
    !isRecord(experience) ||
    !Number.isFinite(Number(experience["total"])) ||
    !Number.isFinite(Number(experience["spent"])) ||
    !Array.isArray(savedLog)
  ) {
    throw new Error(`WFRP4e actor "${actor.name}" does not expose readable XP totals and log.`);
  }

  return {
    awardExperience: async (amount, reason) => {
      const total = Number(experience["total"]) + amount;
      const log = [
        ...savedLog,
        { reason, amount, spent: experience["spent"], total, type: "total" },
      ];
      // WFRP 10.1's awardExp starts update() but returns void. Await the document write
      // ourselves, retaining its XP log format and saving both fields together.
      const updated = await actor.update({
        "system.details.experience.total": total,
        "system.details.experience.log": log,
      });
      if (!updated) throw new Error(`The XP update for ${actor.name} was cancelled.`);
    },
    log: savedLog.map((entry: unknown) =>
      isRecord(entry)
        ? { amount: entry["amount"], reason: entry["reason"], total: entry["total"] }
        : { amount: undefined, reason: undefined, total: undefined },
    ),
    totalXp: Math.max(0, Math.round(Number(experience["total"]))),
  };
}

function getTargetedActorIds(): Set<string> | undefined {
  const targets = game.user?.targets;

  if (!targets || targets.size === 0) {
    return undefined;
  }

  return new Set(
    Array.from(targets)
      .map((token) => token.actor)
      .filter((actor): actor is FoundryActorDocument => actor?.type === "character")
      .map((actor) => actor.id),
  );
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}
