import type { Component } from "vue";
import type { XpAwardSettingsActions } from "../../../../types/xp-award/Console";
import XpAwardSettingsApp from "./XpAwardSettingsApp.vue";
import { MODULE_ID } from "../../../constants";
import { getXpAwardSettings, saveXpAwardSettings } from "../../../foundry/xp-award/settings/load";
import { ToolkitVueApplication } from "../../../foundry/apps/ToolkitVueApplication";
import {
  assertCurrentUserCanAccessApplication,
  TOOLKIT_APPLICATION_ACCESS,
} from "../../../foundry/apps/access";

export class XpAwardSettingsApplication extends ToolkitVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.xpAwards;
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-xp-award-settings`,
    position: { width: 420, height: 390 },
    window: { title: "XP Award Defaults", icon: "fa-solid fa-gear", resizable: true },
  };
  protected override getVueComponent(): Component {
    return XpAwardSettingsApp;
  }
  protected override getVueProps(): Record<string, unknown> {
    const actions: XpAwardSettingsActions = {
      save: async (settings) => {
        assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.xpAwards);
        if (!Number.isSafeInteger(settings.defaultAmount) || settings.defaultAmount === 0)
          throw new Error("Enter a non-zero whole-number XP amount.");
        await saveXpAwardSettings(settings);
        await this.close();
      },
    };
    return { actions, initialization: getXpAwardSettings() };
  }
}
