import { defineStore } from "pinia";
import { computed, ref } from "vue";
import type {
  PartyActions,
  PartyActor,
  PartyConfiguration,
  PartyInitialization,
} from "../../../../types/party/Party";
import { movePartyActor, validatePartyConfiguration } from "../../../functions/party/configuration";

export const useConfigurePartyStore = defineStore("configure-party", () => {
  const configuration = ref<PartyConfiguration>({ version: 1, categories: [] });
  const actors = ref<PartyActor[]>([]);
  const error = ref("");
  const busy = ref(false);
  const saved = ref("");
  const isDirty = computed(() => JSON.stringify(configuration.value) !== saved.value);
  let actions: PartyActions;
  function initialize(data: PartyInitialization, callbacks: PartyActions): void {
    configuration.value = structuredClone(data.configuration);
    actors.value = structuredClone(data.actors);
    actions = callbacks;
    saved.value = JSON.stringify(configuration.value);
  }
  function moveActor(actorId: string, categoryId: string): void {
    configuration.value = movePartyActor(configuration.value, actorId, categoryId);
  }
  function removeActor(actorId: string): void {
    for (const category of configuration.value.categories)
      category.actorIds = category.actorIds.filter((id) => id !== actorId);
  }
  function acceptActor(actor: PartyActor, categoryId: string): void {
    if (!actors.value.some((entry) => entry.id === actor.id)) actors.value.push(actor);
    moveActor(actor.id, categoryId);
  }
  async function drop(data: string, categoryId: string): Promise<void> {
    await run(async () => acceptActor(await actions.resolveDrop(data), categoryId));
  }
  async function addActor(categoryId: string): Promise<void> {
    await run(async () => {
      const category = configuration.value.categories.find((entry) => entry.id === categoryId)!;
      const actor = await actions.pickActor(category);
      if (actor) acceptActor(actor, categoryId);
    });
  }
  async function configure(): Promise<void> {
    await run(async () => {
      const next = await actions.configure(validatePartyConfiguration(configuration.value));
      if (next) configuration.value = validatePartyConfiguration(next);
    });
  }
  async function save(): Promise<void> {
    if (await run(persist)) actions.close();
  }
  async function persist(): Promise<void> {
    await actions.save(validatePartyConfiguration(configuration.value));
    saved.value = JSON.stringify(configuration.value);
  }
  async function canClose(): Promise<boolean> {
    if (busy.value) return false;
    if (!isDirty.value) return true;
    let close = false;
    const success = await run(async () => {
      const decision = await actions.confirmClose();
      if (decision === "save") await persist();
      close = decision === "save" || decision === "discard";
    });
    return success && close;
  }
  async function run(operation: () => Promise<void>): Promise<boolean> {
    if (busy.value) return false;
    busy.value = true;
    error.value = "";
    try {
      await operation();
      return true;
    } catch (cause) {
      error.value = cause instanceof Error ? cause.message : "Could not update the party.";
      return false;
    } finally {
      busy.value = false;
    }
  }
  return {
    configuration,
    actors,
    error,
    busy,
    isDirty,
    canClose,
    initialize,
    moveActor,
    removeActor,
    drop,
    addActor,
    configure,
    save,
    cancel: () => actions.close(),
  };
});
