import { PACKAGE_ID } from "../../constants";
import { openCampaignImport } from "./index";

/** Settings menus require an application class; open the existing native dialog workflow. */
class CampaignImportMenu extends foundry.applications.api.ApplicationV2 {
  override async render(): Promise<this> {
    await openCampaignImport();
    return this;
  }
}

export function registerCampaignImportMenu(): void {
  game?.settings.registerMenu(PACKAGE_ID, "importCampaign", {
    name: "Campaign Content",
    label: "Import Campaign Content",
    hint: "Import or update the content included in this campaign’s compendiums.",
    icon: "fa-solid fa-file-import",
    type: CampaignImportMenu,
    restricted: true,
  });
}
