export function validateCurveInput(value: number, stepIndex: number): string | undefined {
  const step = CURVE_STEPS[stepIndex]!;
  if (!Number.isFinite(value) || value < step.min || value > step.max) {
    return `Enter a value between ${step.min} and ${step.max}.`;
  }
  if (["scalePivot", "maximumAward"].includes(step.key) && !Number.isInteger(value))
    return "Enter a whole XP amount.";
  return undefined;
}
