import type { CampaignSource } from "../../../types/campaign-import";
import { isRecord } from "../../functions/importer/references";

/** Other systems identify protected actors through actual player ownership and assignment. */
export function protectedPlayerCharacterIds(actors: CampaignSource[]): string[] {
  const players = game?.users.contents.filter((user) => !user.isGM) ?? [];
  return actors
    .filter((actor) => {
      if (game?.system.id === "wfrp4e") return actor["type"] === "character";
      const ownership = isRecord(actor["ownership"]) ? actor["ownership"] : {};
      return players.some(
        (user) =>
          user.character?.id === actor._id ||
          Number(ownership[user.id] ?? ownership["default"] ?? 0) >= 3,
      );
    })
    .map((actor) => actor._id);
}

export function actorUpdateOptions(): Record<string, boolean> {
  return game?.system.id === "wfrp4e"
    ? { skipExperienceChecks: true, skipCorruption: true, skipGroupAdvantage: true }
    : {};
}
