import type { Component } from "vue";
import type { PartyConfiguration, PartyInitialization } from "../../../../types/party/Party";
import { MODULE_ID } from "../../../constants";
import { ToolkitVueApplication } from "../../../foundry/apps/ToolkitVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../../../foundry/apps/access";
import {
  getPartyInitialization,
  resolvePartyDrop,
  savePartyConfiguration,
} from "../../../foundry/party/configuration";
import { bindPartyPortraitMenu, pickPartyActor } from "../../../foundry/party/portraits";
import { confirmUnsavedPartyChanges } from "../../../foundry/party/unsaved";
import { PartyZonesApplication } from "./settings/PartyZonesApplication";
import ConfigurePartyApp from "./ConfigurePartyApp.vue";

export class ConfigurePartyApplication extends ToolkitVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.configureParty;
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-configure-party`,
    position: { width: 500, height: 620 },
    window: { title: "Configure Party", icon: "fa-solid fa-people-group", resizable: true },
  };
  private initialization?: PartyInitialization;
  private zones: PartyZonesApplication | undefined;
  private closeGuard?: () => Promise<boolean>;
  private closing = false;

  private async configureZones(
    configuration: PartyConfiguration,
  ): Promise<PartyConfiguration | null> {
    let finish!: (value: PartyConfiguration | null) => void;
    const result = new Promise<PartyConfiguration | null>((resolve) => {
      finish = resolve;
    });
    this.zones = new PartyZonesApplication(configuration, finish);
    try {
      await this.zones.render(true);
      return await result;
    } finally {
      this.zones = undefined;
    }
  }

  override async close(): Promise<this> {
    if (this.closing) return this;
    this.closing = true;
    try {
      const zones = this.zones;
      await zones?.close();
      if (zones?.rendered) return this;
      if (this.closeGuard && !(await this.closeGuard())) return this;
      return await super.close();
    } finally {
      this.closing = false;
    }
  }

  override async render(force?: boolean): Promise<this> {
    // The inherited GM guard also runs before mounting.
    if (!ConfigurePartyApplication.canCurrentUserAccess()) return super.render(force);
    this.initialization = await getPartyInitialization();
    return super.render(force);
  }
  protected override getVueComponent(): Component {
    return ConfigurePartyApp;
  }
  protected override getVueProps(): Record<string, unknown> {
    return {
      initialization: this.initialization,
      actions: {
        resolveDrop: resolvePartyDrop,
        save: savePartyConfiguration,
        configure: (configuration: PartyConfiguration) => this.configureZones(configuration),
        bindMenu: bindPartyPortraitMenu,
        pickActor: pickPartyActor,
        bindCloseGuard: (guard: () => Promise<boolean>) => {
          this.closeGuard = guard;
        },
        confirmClose: () => confirmUnsavedPartyChanges(),
        close: () => {
          void this.close();
        },
      },
    };
  }
}

export async function openConfigureParty(): Promise<ConfigurePartyApplication> {
  const application = new ConfigurePartyApplication();
  await application.render(true);
  return application;
}
