import type { PartyActor, PartyCategory, PartyPortraitMenu } from "../../../types/party/Party";
import { getPartyActorChoices } from "./configuration";
import { escapeHtml } from "../../functions/xp-curve/reason";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";

export function bindPartyPortraitMenu(root: HTMLElement, callbacks: PartyPortraitMenu): () => void {
  // Foundry renders native menu entries as non-focusable list items.
  class PortraitMenu extends foundry.applications.ux.ContextMenu {
    override activateListeners(element: HTMLElement): void {
      super.activateListeners(element);
      element.setAttribute("role", "menu");
      const items = Array.from(element.querySelectorAll<HTMLElement>(".context-item"));
      for (const item of items) {
        item.tabIndex = 0;
        item.setAttribute("role", "menuitem");
      }
      element.addEventListener("keydown", (event) => {
        const index = items.indexOf(document.activeElement as HTMLElement);
        if (["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) {
          event.preventDefault();
          event.stopPropagation();
          const next =
            event.key === "Home"
              ? 0
              : event.key === "End"
                ? items.length - 1
                : (index + (event.key === "ArrowDown" ? 1 : -1) + items.length) % items.length;
          items[next]?.focus();
        } else if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          event.stopPropagation();
          items[index]?.click();
        } else if (event.key === "Escape") {
          event.preventDefault();
          event.stopPropagation();
          void this.close();
          this.target.focus();
        }
      });
    }
    override async render(target: HTMLElement, options?: { event?: Event }): Promise<void> {
      await super.render(target, options);
      this.element?.querySelector<HTMLElement>(".context-item")?.focus();
    }
  }
  const menu = new PortraitMenu(root, "[data-party-actor]", [], {
    jQuery: false,
    fixed: true,
    relative: "target",
    onOpen: (target) => {
      const id = target.dataset["partyActor"]!;
      const actor = game.actors.get(id);
      const run = (operation: () => void): void => {
        if (callbacks.busy()) return;
        assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.configureParty);
        operation();
      };
      menu.menuItems = callbacks.busy()
        ? []
        : [
            ...(actor
              ? [
                  entry("Open character sheet", "fa-user", () =>
                    run(() => {
                      actor.sheet?.render(true);
                    }),
                  ),
                ]
              : []),
            ...callbacks
              .categories()
              .filter((category) => !category.actorIds.includes(id))
              .map((category) =>
                entry(`Move to ${category.name}`, "fa-arrow-right", () =>
                  run(() => callbacks.move(id, category.id)),
                ),
              ),
            entry("Remove from roster", "fa-user-minus", () => run(() => callbacks.remove(id))),
          ];
    },
  });
  return () => {
    if (menu.element?.isConnected) void menu.close({ animate: false });
  };
}

function entry(
  label: string,
  icon: string,
  action: () => void,
): foundry.applications.ux.ContextMenuEntry {
  // v13 uses name/callback and HTML icons; v14 prefers label/onClick.
  return {
    label,
    name: escapeHtml(label),
    icon: `<i class="fa-solid ${icon}"></i>`,
    onClick: action,
    callback: action,
  };
}

export async function pickPartyActor(category: PartyCategory): Promise<PartyActor | null> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.configureParty);
  const actors = getPartyActorChoices().filter((actor) => !category.actorIds.includes(actor.id));
  if (!actors.length) throw new Error("Every available character is already in this zone.");
  const result = await foundry.applications.api.DialogV2.input({
    modal: true,
    window: { title: `Add actor to ${category.name}` },
    content: `<label class="form-group"><span>Character</span><select name="actor">${actors.map((actor) => `<option value="${escapeHtml(actor.id)}">${escapeHtml(actor.name)}</option>`).join("")}</select></label>`,
    ok: { label: "Add actor" },
    rejectClose: false,
  });
  return result ? (actors.find((actor) => actor.id === result["actor"]) ?? null) : null;
}

export async function confirmRemovePartyZone(category: PartyCategory): Promise<boolean> {
  if (!category.actorIds.length) return true;
  return (
    (await foundry.applications.api.DialogV2.confirm({
      modal: true,
      window: { title: "Remove zone?" },
      rejectClose: false,
      content: `<p>Remove ${escapeHtml(category.name)} and its ${category.actorIds.length} roster members?</p><p>The actors themselves are kept.</p>`,
    })) === true
  );
}
