import { computed } from "vue";
import type { CurveStep } from "../../../../../types/xp-curve/Configuration";
import type { XpActorChoice, XpCurveParameters } from "../../../../../types/xp-curve/XpCurve";
import type { CurveGraphBounds, CurveGraphProjection } from "../../../../../types/xp-curve/Graph";
import { buildCurveGraph, curveValueFromPointer } from "../../../../functions/xp-curve/graph";
import { CURVE_STEPS } from "../../../../functions/xp-curve/setup";
import { useGraphDrag } from "./graph/drag";
import { getGraphPointerPosition } from "./graphMath";

export interface StepGraphProps {
  actors: XpActorChoice[];
  parameters: XpCurveParameters;
  step: CurveStep;
}

export function useStepGraph(
  props: StepGraphProps,
  emit: (key: keyof XpCurveParameters, value: number) => void,
) {
  const { activeDrag, beginDrag, endDrag, updateDrag } = useGraphDrag<
    Exclude<CurveStep, "review">,
    CurveGraphBounds
  >(
    (): CurveGraphBounds => graph.value.bounds,
    (drag, event) =>
      emit(
        drag.kind,
        curveValueFromPointer(
          drag.kind,
          getGraphPointerPosition(drag.svg, event),
          drag.snapshot,
          props.parameters,
        ),
      ),
  );
  const graph = computed<CurveGraphProjection>((previous) =>
    buildCurveGraph(props.step, props.actors, props.parameters, {
      previous: previous?.bounds,
      frozen: activeDrag.value?.snapshot,
    }),
  );
  const definition = computed(() => CURVE_STEPS.find((entry) => entry.key === props.step)!);
  function start(event: PointerEvent): void {
    if (props.step !== "review") beginDrag(props.step, event);
  }
  function keydown(event: KeyboardEvent): void {
    if (
      props.step === "review" ||
      !["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(event.key)
    )
      return;
    event.preventDefault();
    const sign = event.key === "ArrowUp" || event.key === "ArrowRight" ? 1 : -1;
    const direction = props.step === "scaleExponent" ? -sign : sign;
    const next = props.parameters[props.step] + direction * definition.value.increment;
    emit(
      props.step,
      Math.round(Math.max(definition.value.min, Math.min(definition.value.max, next)) * 100) / 100,
    );
  }
  return { graph, definition, start, endDrag, updateDrag, keydown };
}
